local factories, cache, loading = {}, {}, {}
local function requireOC(name)
  if cache[name] ~= nil then return cache[name] end
  assert(factories[name], "[OC] Unknown bundled module: " .. tostring(name))
  assert(not loading[name], "[OC] Circular bundled dependency: " .. tostring(name))
  loading[name] = true
  local ok, result = pcall(factories[name])
  loading[name] = nil
  if not ok then error("[OC] Module " .. name .. " failed: " .. tostring(result), 0) end
  cache[name] = result
  return result
end

-- src/OCFoundation/AccountPresentation.luau
factories["AccountPresentation"] = function()
--!nonstrict
-- Only formats values supplied by the account reader. Unknown stays unavailable.
local AccountPresentation = {}

function AccountPresentation.Number(value)
	if type(value) ~= "number" then return "unavailable" end
	if value == math.huge then return "unlimited" end
	return tostring(value)
end

local function keys(map)
	local result = {}
	for key in pairs(map) do table.insert(result, key) end
	table.sort(result, function(a, b) return tostring(a) < tostring(b) end)
	return result
end

function AccountPresentation.Describe(value, depth, seen)
	if value == nil then return "unavailable" end
	if type(value) ~= "table" then return tostring(value) end
	depth = depth or 0
	seen = seen or {}
	if seen[value] then return "<cycle>" end
	local sorted = keys(value)
	if depth >= 2 then return "<" .. tostring(#sorted) .. " entries>" end
	seen[value] = true
	local lines = {}
	for index, key in ipairs(sorted) do
		if index > 10 then table.insert(lines, "... " .. tostring(#sorted - 10) .. " more fields") break end
		table.insert(lines, tostring(key) .. "=" .. AccountPresentation.Describe(value[key], depth + 1, seen))
	end
	seen[value] = nil
	return "{" .. table.concat(lines, ", ") .. "}"
end

function AccountPresentation.List(map, limit)
	if type(map) ~= "table" then return "unavailable" end
	local sorted = keys(map)
	if #sorted == 0 then return "(empty received table)" end
	local lines = {}
	for index, key in ipairs(sorted) do
		if index > limit then table.insert(lines, "... " .. tostring(#sorted - limit) .. " more entries; GetStatus has the complete snapshot") break end
		table.insert(lines, tostring(key) .. ": " .. AccountPresentation.Describe(map[key]))
	end
	return table.concat(lines, "\n")
end

function AccountPresentation.Sections(snapshot, config, limit)
	local sections = {}
	local inventory, bubble, upgrades = snapshot.Inventory or {}, snapshot.Bubble or {}, snapshot.Upgrades or {}
	local balances = {}
	local displayed = {}
	for _, name in ipairs(config.ACCOUNT_SETTINGS.SELECTED_CURRENCIES) do
		table.insert(balances, name .. ": " .. AccountPresentation.Number((snapshot.Balances or {})[name]))
		displayed[name] = true
	end
	for _, name in ipairs(keys(snapshot.Balances or {})) do
		if not displayed[name] then table.insert(balances, name .. ": " .. AccountPresentation.Number(snapshot.Balances[name])) end
	end
	table.insert(balances, "Bubbles: " .. AccountPresentation.Number(bubble.Amount) .. " / " .. AccountPresentation.Number(bubble.Capacity))
	table.insert(balances, "Power per blow: " .. AccountPresentation.Number(bubble.PowerPerBlow))
	table.insert(balances, "Equipped gum: " .. tostring(bubble.Gum or "unavailable") .. "; flavor: " .. tostring(bubble.Flavor or "unavailable"))
	sections.Balances = table.concat(balances, "\n")
	sections.Pets = "Active team: " .. tostring(inventory.TeamEquipped or "unavailable")
		.. "\nEquip limit: " .. AccountPresentation.Number(inventory.MaxEquipped)
		.. "\nEquipped IDs:\n" .. AccountPresentation.List(inventory.EquippedIds, limit)
		.. "\nEquipped records:\n" .. (inventory.EquippedIds and AccountPresentation.List(inventory.EquippedPets, limit) or "unavailable")
		.. "\nUnresolved equipped IDs:\n" .. (inventory.EquippedIds and AccountPresentation.List(inventory.UnresolvedEquippedIds, limit) or "unavailable")
		.. "\nPet inventory:\n" .. AccountPresentation.List(inventory.Pets, limit)
	sections.Inventory = "Storage used / capacity (game-defined units): " .. AccountPresentation.Number(inventory.StorageUsed)
		.. " / " .. AccountPresentation.Number(inventory.StorageCapacity)
		.. "\nPowerups:\n" .. AccountPresentation.List(inventory.Powerups, limit)
		.. "\nPotions:\n" .. AccountPresentation.List(inventory.Potions, limit)
	sections.Worlds = "Unlocked worlds:\n" .. AccountPresentation.List(snapshot.UnlockedWorlds, limit)
		.. "\nDiscovered islands:\n" .. AccountPresentation.List(snapshot.UnlockedIslands, limit)
	sections.Upgrades = "Owned gum:\n" .. AccountPresentation.List(upgrades.Gum, limit)
		.. "\nOwned flavors:\n" .. AccountPresentation.List(upgrades.Flavors, limit)
		.. "\nMastery upgrades:\n" .. AccountPresentation.List(upgrades.MasteryUpgrades, limit)
	sections.Mastery = "Received levels:\n" .. AccountPresentation.List(upgrades.MasteryLevels, limit)
		.. "\nVerified next tiers:\n" .. AccountPresentation.List(snapshot.AvailableProgression and snapshot.AvailableProgression.Mastery, limit)
	return sections
end

return AccountPresentation

end

-- src/OCFoundation/AccountStateReader.luau
factories["AccountStateReader"] = function()
--!nonstrict
-- Read-only adapter for this workspace's LocalData and Shared game definitions.
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local CollectionService = game:GetService("CollectionService")

local AccountStateReader = {}
AccountStateReader.__index = AccountStateReader

local function copy(value, seen)
	if type(value) ~= "table" then return value end
	seen = seen or {}
	if seen[value] then return seen[value] end
	local result = {}
	seen[value] = result
	for key, entry in pairs(value) do result[key] = copy(entry, seen) end
	return result
end

local function number(value)
	if type(value) == "number" and value == value and value >= 0 then return value end
	return nil
end

local function findPath(path)
	local node = ReplicatedStorage
	for name in string.gmatch(path, "[^%.]+") do
		node = node and node:FindFirstChild(name)
	end
	return node
end

local function allowed(list, name)
	return #list == 0 or table.find(list, name) ~= nil
end

function AccountStateReader.new(config, player)
	local self = setmetatable({}, AccountStateReader)
	self.Config = config
	self.Player = player or Players.LocalPlayer
	self.Changed = Instance.new("BindableEvent")
	self.Dependencies = {}
	self.Connections = {}
	self.Threads = {}
	self.Destroyed = false
	self.StartedAt = nil
	self.Revision = 0
	self.DiscoveredCurrencies = {}
	self.Snapshot = { Ready = false, Status = "NOT_STARTED", Diagnostics = {}, Revision = 0 }
	return self
end

function AccountStateReader:_load(name, path, expectedType)
	local entry = { Status = "LOADING", Path = path }
	self.Dependencies[name] = entry
	local module = findPath(path)
	if not module or not module:IsA("ModuleScript") then
		entry.Status = "MISSING"
		entry.Error = "ModuleScript is absent: " .. path
		return
	end
	table.insert(self.Threads, task.defer(function()
		local ok, result = pcall(require, module)
		if self.Destroyed then return end
		if ok and type(result) ~= (expectedType or "table") then
			ok = false
			result = "Observed game interface requires " .. (expectedType or "table") .. "; module returned " .. type(result)
		end
		entry.Status = ok and "READY" or "ERROR"
		entry.Value = ok and result or nil
		entry.Error = not ok and tostring(result) or nil
		if name == "LocalData" and ok and type(result) == "table" then
			for _, signalName in ipairs({ "Changed", "DataReady", "PetsChanged" }) do
				local signal = result[signalName]
				if typeof(signal) == "RBXScriptSignal" then
					table.insert(self.Connections, signal:Connect(function() self:_queueRefresh() end))
				end
			end
		end
		self:Refresh()
	end))
	table.insert(self.Threads, task.delay(self.Config.ACCOUNT_SETTINGS.MODULE_LOAD_TIMEOUT_SECONDS, function()
		if self.Destroyed or entry.Status ~= "LOADING" then return end
		entry.Status = "TIMED_OUT"
		entry.Error = "Game module has not finished loading: " .. path
		self:Refresh()
	end))
end

function AccountStateReader:_dependency(name)
	local entry = self.Dependencies[name]
	return entry and entry.Status == "READY" and entry.Value or nil
end

function AccountStateReader:_stat(method, raw, diagnostics)
	local stats = self:_dependency("StatsUtil")
	if not stats then return nil end
	if type(stats[method]) ~= "function" then
		table.insert(diagnostics, "StatsUtil is missing method " .. method)
		return nil
	end
	local ok, result = pcall(stats[method], stats, raw)
	if not ok then
		table.insert(diagnostics, method .. " failed: " .. tostring(result))
		return nil
	end
	return number(result)
end

function AccountStateReader:_catalog(snapshot)
	local result = { Worlds = {}, Islands = {}, Upgrades = {}, Mastery = {} }
	local worlds = self:_dependency("Worlds")
	local sceneWorlds = workspace:FindFirstChild("Worlds")
	local gates = {}
	for _, gate in ipairs(CollectionService:GetTagged("WorldGate")) do
		local destination = gate:GetAttribute("World")
		if type(destination) == "string" and gate:IsDescendantOf(workspace) then
			local node, area, origin = gate, nil, nil
			while node and node ~= workspace do
				if node.Parent and node.Parent.Name == "Islands" then area = node.Name end
				if node.Parent == sceneWorlds then origin = node.Name end
				node = node.Parent
			end
			gates[destination] = { RequiredIsland = area, OriginWorld = origin, Path = gate:GetFullName() }
		end
	end
	if type(worlds) == "table" and sceneWorlds then
		for name, definition in pairs(worlds) do
			-- A retained seasonal definition is not proof that its event is active.
			if type(definition) == "table" and not definition.Event and not definition.Removed and sceneWorlds:FindFirstChild(name) then
				local gate = gates[name]
				table.insert(result.Worlds, {
					Name = name, Order = definition.Order or 999,
					Cost = copy(definition.UnlockCost), Gate = gate,
					Unlocked = snapshot.UnlockedWorlds and snapshot.UnlockedWorlds[name] ~= nil,
					Selected = allowed(self.Config.BRAIN_SETTINGS.SELECTED_WORLDS, name),
				})
				local islandRoot = sceneWorlds[name]:FindFirstChild("Islands")
				for _, island in ipairs(definition.Islands or {}) do
					local instance = islandRoot and islandRoot:FindFirstChild(island.Name)
					if instance then
						table.insert(result.Islands, {
							Name = island.Name, World = name,
							Height = instance:GetAttribute("Height") or island.Height,
							Unlocked = snapshot.UnlockedIslands and snapshot.UnlockedIslands[island.Name] ~= nil,
						})
					end
				end
			end
		end
	end
	table.sort(result.Worlds, function(a, b) return a.Order < b.Order end)
	table.sort(result.Islands, function(a, b)
		if a.World == b.World then return (a.Height or math.huge) < (b.Height or math.huge) end
		return a.World < b.World
	end)
	for _, kind in ipairs({ "Gum", "Flavors" }) do
		local definitions = self:_dependency(kind)
		if type(definitions) == "table" then
			for name, definition in pairs(definitions) do
				if type(definition) == "table" and type(definition.Cost) == "table"
					and definition.Cost.Type == "Currency" and allowed(self.Config.BRAIN_SETTINGS.SELECTED_UPGRADES, name) then
					local accessKnown = definition.Area == nil or (snapshot.UnlockedWorlds ~= nil and snapshot.UnlockedIslands ~= nil)
					local accessible = definition.Area == nil or (accessKnown and (snapshot.UnlockedWorlds[definition.Area] ~= nil
						or snapshot.UnlockedIslands[definition.Area] ~= nil))
					local owned = kind == "Gum" and snapshot.Upgrades.Gum or snapshot.Upgrades.Flavors
					table.insert(result.Upgrades, {
						Name = name, Kind = kind, Cost = copy(definition.Cost), Area = definition.Area,
						BaseStat = number(kind == "Gum" and definition.Storage or definition.Bubbles),
						Accessible = accessible == true, AccessKnown = accessKnown,
						Owned = owned and owned[name] ~= nil, OwnershipKnown = owned ~= nil,
					})
				end
			end
		end
	end
	local mastery = self:_dependency("Mastery")
	if type(mastery) == "table" then
		for _, branch in ipairs(self.Config.BRAIN_SETTINGS.MASTERY_PRIORITIES) do
			local definition = mastery[branch]
			local current = snapshot.Upgrades.MasteryLevels and number(snapshot.Upgrades.MasteryLevels[branch])
			-- Never infer a missing Mastery level as level zero.
			if type(definition) == "table" and type(definition.Levels) == "table" then
				local maximum = 0
				for level in pairs(definition.Levels) do if type(level) == "number" then maximum = math.max(maximum, level) end end
				local nextLevel = current and definition.Levels[current + 1]
				table.insert(result.Mastery, {
					Name = branch, Current = current, Maximum = maximum,
					NextCost = nextLevel and copy(nextLevel.Cost),
					NextUpgrades = nextLevel and copy(nextLevel.Upgrades),
				})
			end
		end
	end
	return result
end

function AccountStateReader:Read()
	local diagnostics = {}
	for name, entry in pairs(self.Dependencies) do
		if entry.Status ~= "READY" then table.insert(diagnostics, name .. ": " .. (entry.Error or entry.Status)) end
	end
	local snapshot = {
		Ready = false, Status = "WAITING_FOR_ACCOUNT", Diagnostics = diagnostics,
		Revision = self.Revision + 1, ReadAt = os.clock(),
		Identity = self.Player and { UserId = self.Player.UserId, AccountAge = self.Player.AccountAge } or {},
		Balances = {}, Bubble = {}, Inventory = {}, Upgrades = {}, UnavailableFields = {}, Dependencies = {},
	}
	for name, entry in pairs(self.Dependencies) do
		snapshot.Dependencies[name] = { Status = entry.Status, Path = entry.Path, Error = entry.Error }
	end
	local settings = self.Config.ACCOUNT_SETTINGS
	if not settings.ENABLE_ACCOUNT_READER then
		snapshot.Status = "READER_DISABLED"
		table.insert(diagnostics, "Account reading is disabled in OCConfig.")
	else
		local service = self:_dependency("LocalData")
		if service and type(service.IsReady) == "function" and type(service.Get) == "function" then
			local readyOK, ready = pcall(service.IsReady, service)
			local dataOK, raw = pcall(service.Get, service)
			if readyOK and ready and dataOK and type(raw) == "table" then
				snapshot.Ready = true
				snapshot.Status = "READY"
				snapshot.Source = "ReplicatedStorage.Client.Framework.Services.LocalData:Get()"
				for _, currency in ipairs(settings.SELECTED_CURRENCIES) do
					snapshot.Balances[currency] = number(raw[currency])
				end
				for currency in pairs(self.DiscoveredCurrencies) do snapshot.Balances[currency] = number(raw[currency]) end
				if type(raw.Bubble) == "table" then
					snapshot.Bubble.Amount = number(raw.Bubble.Amount)
					snapshot.Bubble.Gum = raw.Bubble.Gum
					snapshot.Bubble.Flavor = raw.Bubble.Flavor
				end
				snapshot.Bubble.Capacity = self:_stat("GetBubbleStorage", raw, diagnostics)
				snapshot.Bubble.PowerPerBlow = self:_stat("GetBubblePower", raw, diagnostics)
				local gum, flavors = self:_dependency("Gum"), self:_dependency("Flavors")
				local gumDefinition = gum and gum[snapshot.Bubble.Gum]
				local flavorDefinition = flavors and flavors[snapshot.Bubble.Flavor]
				snapshot.Bubble.BaseCapacity = gumDefinition and number(gumDefinition.Storage)
				snapshot.Bubble.BaseOutput = flavorDefinition and number(flavorDefinition.Bubbles)
				if settings.READ_PET_INVENTORY then
					snapshot.Inventory.Pets = type(raw.Pets) == "table" and copy(raw.Pets) or nil
					snapshot.Inventory.Teams = type(raw.Teams) == "table" and copy(raw.Teams) or nil
					snapshot.Inventory.TeamEquipped = raw.TeamEquipped
					local team = snapshot.Inventory.Teams and snapshot.Inventory.Teams[raw.TeamEquipped]
					snapshot.Inventory.EquippedIds = team and type(team.Pets) == "table" and copy(team.Pets) or nil
					snapshot.Inventory.EquippedPets = {}
					snapshot.Inventory.UnresolvedEquippedIds = {}
					if snapshot.Inventory.Pets and snapshot.Inventory.EquippedIds then
						local byId = {}
						for _, pet in pairs(snapshot.Inventory.Pets) do
							if type(pet) == "table" and type(pet.Id) == "string" then byId[pet.Id] = pet end
						end
						for _, id in ipairs(snapshot.Inventory.EquippedIds) do
							if byId[id] then table.insert(snapshot.Inventory.EquippedPets, byId[id])
							else table.insert(snapshot.Inventory.UnresolvedEquippedIds, id) end
						end
					end
					snapshot.Inventory.MaxEquipped = self:_stat("GetMaxPetsEquipped", raw, diagnostics)
					snapshot.Inventory.StorageCapacity = self:_stat("GetMaxPetStorage", raw, diagnostics)
					snapshot.Inventory.StorageUsed = self:_stat("GetUsedPetStorage", raw, diagnostics)
				end
				if settings.READ_ITEM_INVENTORY then
					snapshot.Inventory.Powerups = type(raw.Powerups) == "table" and copy(raw.Powerups) or nil
					snapshot.Inventory.Potions = type(raw.Potions) == "table" and copy(raw.Potions) or nil
				end
				if settings.READ_UPGRADES then
					snapshot.Upgrades.Gum = type(raw.Gum) == "table" and copy(raw.Gum) or nil
					snapshot.Upgrades.Flavors = type(raw.Flavors) == "table" and copy(raw.Flavors) or nil
				end
				if settings.READ_MASTERY then
					snapshot.Upgrades.MasteryLevels = type(raw.MasteryLevels) == "table" and copy(raw.MasteryLevels) or nil
					snapshot.Upgrades.MasteryUpgrades = type(raw.MasteryUpgrades) == "table" and copy(raw.MasteryUpgrades) or nil
				end
				if settings.READ_UNLOCKS then
					snapshot.UnlockedIslands = type(raw.AreasUnlocked) == "table" and copy(raw.AreasUnlocked) or nil
					snapshot.UnlockedWorlds = type(raw.WorldsUnlocked) == "table" and copy(raw.WorldsUnlocked) or nil
				end
			elseif type(service.DidLoadFail) == "function" then
				local ok, failed = pcall(service.DidLoadFail, service)
				if ok and failed then snapshot.Status = "ACCOUNT_LOAD_FAILED" end
			end
			if not readyOK then table.insert(diagnostics, "LocalData:IsReady failed: " .. tostring(ready)) end
			if not dataOK then table.insert(diagnostics, "LocalData:Get failed: " .. tostring(raw)) end
		end
		if not snapshot.Ready and self.StartedAt and os.clock() - self.StartedAt >= settings.ACCOUNT_LOAD_TIMEOUT_SECONDS then
			if snapshot.Status == "WAITING_FOR_ACCOUNT" then snapshot.Status = "ACCOUNT_DATA_UNAVAILABLE" end
			table.insert(diagnostics, "No ready player profile was received from LocalData. Check its module status and whether your client received PlayerDataLoaded. No statistics have been substituted.")
		end
	end
	if snapshot.Ready then
		for name, value in pairs({ Coins = not table.find(settings.SELECTED_CURRENCIES, "Coins") or snapshot.Balances.Coins ~= nil,
			Gems = not table.find(settings.SELECTED_CURRENCIES, "Gems") or snapshot.Balances.Gems ~= nil,
			Bubbles = snapshot.Bubble.Amount ~= nil, Capacity = snapshot.Bubble.Capacity ~= nil,
			PetInventory = not settings.READ_PET_INVENTORY or snapshot.Inventory.Pets ~= nil,
			EquippedPets = not settings.READ_PET_INVENTORY or snapshot.Inventory.EquippedIds ~= nil,
			Powerups = not settings.READ_ITEM_INVENTORY or snapshot.Inventory.Powerups ~= nil,
			Potions = not settings.READ_ITEM_INVENTORY or snapshot.Inventory.Potions ~= nil,
			Mastery = not settings.READ_MASTERY or snapshot.Upgrades.MasteryLevels ~= nil,
			MasteryUpgrades = not settings.READ_MASTERY or snapshot.Upgrades.MasteryUpgrades ~= nil,
			Upgrades = not settings.READ_UPGRADES or (snapshot.Upgrades.Gum ~= nil and snapshot.Upgrades.Flavors ~= nil),
			Islands = not settings.READ_UNLOCKS or snapshot.UnlockedIslands ~= nil,
			Worlds = not settings.READ_UNLOCKS or snapshot.UnlockedWorlds ~= nil }) do
			if not value then table.insert(snapshot.UnavailableFields, name) end
		end
		if #snapshot.UnavailableFields > 0 then snapshot.Status = "PARTIAL_ACCOUNT_DATA" end
	end
	snapshot.AvailableProgression = settings.ENABLE_ACCOUNT_READER and self:_catalog(snapshot) or {}
	table.sort(diagnostics)
	return snapshot
end

function AccountStateReader:_queueRefresh()
	if self.Destroyed or self.RefreshThread then return end
	local interval = self.Config.ACCOUNT_SETTINGS.MINIMUM_SNAPSHOT_INTERVAL_SECONDS
	local waitSeconds = math.max(0, interval - (os.clock() - (self.LastRefreshAt or -math.huge)))
	self.RefreshThread = task.delay(waitSeconds, function()
		self.RefreshThread = nil
		if not self.Destroyed then self:Refresh() end
	end)
end

function AccountStateReader:Refresh()
	if self.Destroyed then return end
	self.LastRefreshAt = os.clock()
	local ok, result = xpcall(function() return self:Read() end, debug.traceback)
	if not ok then
		result = { Ready = false, Status = "READER_ERROR", Revision = self.Revision + 1,
			Diagnostics = { tostring(result) }, UnavailableFields = {}, AvailableProgression = {} }
	end
	self.Revision = result.Revision
	self.Snapshot = result
	self.Changed:Fire(result)
end

function AccountStateReader:GetSnapshot()
	return copy(self.Snapshot)
end

-- Internal consumers treat this native profile as read-only. No writes or synthetic values.
function AccountStateReader:GetLiveProfile()
	if self.Destroyed or not self.Config.ACCOUNT_SETTINGS.ENABLE_ACCOUNT_READER then return nil end
	local service = self:_dependency("LocalData")
	if not service or type(service.Get) ~= "function" or type(service.IsReady) ~= "function" then return nil end
	local ok, ready = pcall(service.IsReady, service)
	if not ok or not ready then return nil end
	local received, profile = pcall(service.Get, service)
	return received and type(profile) == "table" and profile or nil
end

function AccountStateReader:RegisterCurrency(name)
	if type(name) == "string" then self.DiscoveredCurrencies[name] = true end
end

function AccountStateReader:ReadBalances()
	local raw, result = self:GetLiveProfile(), {}
	if not raw then return result end
	for _, name in ipairs(self.Config.ACCOUNT_SETTINGS.SELECTED_CURRENCIES) do result[name] = number(raw[name]) end
	for name in pairs(self.DiscoveredCurrencies) do result[name] = number(raw[name]) end
	return result
end

function AccountStateReader:Start()
	if self.StartedAt or self.Destroyed then return end
	self.StartedAt = os.clock()
	if self.Config.ACCOUNT_SETTINGS.ENABLE_ACCOUNT_READER then
		if RunService:IsClient() then self:_load("LocalData", "Client.Framework.Services.LocalData")
		else self.Dependencies.LocalData = { Status = "ERROR", Path = "Client.Framework.Services.LocalData", Error = "Client runtime is required" } end
		for name, path in pairs({ Worlds = "Shared.Data.Worlds", Gum = "Shared.Data.Gum",
			Flavors = "Shared.Data.Flavors", Mastery = "Shared.Data.Mastery", StatsUtil = "Shared.Utils.Stats.StatsUtil" }) do
			self:_load(name, path)
		end
		if self.Config.FARMING_SETTINGS.AUTO_RESOURCE_FARM then
			self:_load("GetPickupZones", "Shared.Utils.GetPickupZones", "function")
			self:_load("Remote", "Shared.Framework.Network.Remote")
			self:_load("GuiFrame", "Client.Gui.GuiFrame")
			self:_load("PhysicalItem", "Client.Effects.PhysicalItem")
			self:_load("FishingPlayerRods", "Client.Gui.Frames.Fishing.FishingPlayerRods")
			self:_load("IsTradingPlaza", "Shared.Utils.IsTradingPlaza", "function")
		end
	end
	self:Refresh()
	if not self.Config.ACCOUNT_SETTINGS.ENABLE_ACCOUNT_READER then return end
	table.insert(self.Threads, task.spawn(function()
		while not self.Destroyed do
			task.wait(self.Config.ACCOUNT_SETTINGS.SNAPSHOT_REFRESH_SECONDS)
			if not self.Destroyed then self:Refresh() end
		end
	end))
end

function AccountStateReader:Destroy()
	if self.Destroyed then return end
	self.Destroyed = true
	if self.RefreshThread then pcall(task.cancel, self.RefreshThread) end
	for _, connection in ipairs(self.Connections) do connection:Disconnect() end
	for _, thread in ipairs(self.Threads) do pcall(task.cancel, thread) end
	self.Changed:Destroy()
end

return AccountStateReader

end

-- src/OCFoundation/ConfigResolver.luau
factories["ConfigResolver"] = function()
--!nonstrict
-- Overrides replace setting values, including entire arrays; the defaults are never mutated.
local ConfigResolver = {}

local function copy(value)
	if type(value) ~= "table" then return value end
	local result = {}
	for key, item in pairs(value) do result[key] = copy(item) end
	return result
end

function ConfigResolver.Resolve(defaults, overrides)
	assert(overrides == nil or type(overrides) == "table", "[OC] Config must be a table")
	local result = copy(defaults)
	for category, values in pairs(overrides or {}) do
		assert(defaults[category] ~= nil, "[OC] Unknown configuration category: " .. tostring(category))
		assert(type(values) == "table", "[OC] " .. category .. " must be a table")
		for key, value in pairs(values) do
			local expected = defaults[category][key]
			local path = category .. "." .. tostring(key)
			assert(expected ~= nil, "[OC] Unknown configuration setting: " .. path)
			assert(type(value) == type(expected), "[OC] " .. path .. " must be a " .. type(expected))
			if type(value) == "table" then
				local count = 0
				for index, item in pairs(value) do
					assert(type(index) == "number" and index >= 1 and index % 1 == 0 and type(item) == "string",
						"[OC] " .. path .. " must be an array of strings")
					count += 1
				end
				for index = 1, count do assert(value[index] ~= nil, "[OC] Sparse array: " .. path) end
			end
			result[category][key] = copy(value)
		end
	end
	return result
end

return ConfigResolver

end

-- src/OCFoundation/FarmingCoordinator.luau
factories["FarmingCoordinator"] = function()
--!nonstrict
-- Observations may run in the background; every action is an OCBrain-selected scheduler task.
local PickupTracker = requireOC("PickupTracker")
local GameMechanics = requireOC("GameMechanics")
local ResourceMetrics = requireOC("ResourceMetrics")
local FarmingPolicy = requireOC("FarmingPolicy")
local FarmingCoordinator = {}
FarmingCoordinator.__index = FarmingCoordinator

local function balancesText(values)
	local items = {}
	for name, amount in pairs(values) do table.insert(items, string.format("%s=%.0f", name, amount)) end
	table.sort(items)
	return #items > 0 and table.concat(items, ", ") or "unavailable"
end

function FarmingCoordinator.new(controller, player)
	local self = setmetatable({ Controller = controller, Config = controller.Config, Reader = controller.Reader,
		Activity = nil, Decision = nil, Destroyed = false, LastLogAt = -math.huge, SaleEvidence = {}, ProbeStart = nil }, FarmingCoordinator)
	self.Tracker = PickupTracker.new(self.Config, self.Reader, player)
	self.Mechanics = GameMechanics.new(self.Config, self.Reader, self.Tracker, player)
	self.Metrics = ResourceMetrics.new(self.Config.FARMING_SETTINGS)
	return self
end

function FarmingCoordinator:Observe()
	if self.Destroyed or not self.Config.FARMING_SETTINGS.AUTO_RESOURCE_FARM then return end
	local now, snapshot = os.clock(), self.Reader:GetSnapshot()
	local ok, reason = xpcall(function() self.Tracker:Refresh(snapshot, now) end, debug.traceback)
	if not ok then self.Tracker.Error = tostring(reason) end
	local balances = self.Reader:ReadBalances()
	local gains = self.Metrics:Observe(balances, now)
	local live = self.Reader:GetLiveProfile()
	local amount = live and live.Bubble and live.Bubble.Amount
	if self.Controller.State == "RUNNING" and self.Metrics.Active and type(amount) == "number" and type(self.LastBubbleAmount) == "number"
		and amount < self.LastBubbleAmount then
		self.PendingSale = { Scope = self.Metrics.Active.Scope, ExpiresAt = now + self.Config.FARMING_SETTINGS.EARNINGS_CONFIRMATION_TIMEOUT_SECONDS }
	end
	if self.PendingSale and next(gains) and now <= self.PendingSale.ExpiresAt then
		self.SaleEvidence[self.PendingSale.Scope] = true self.ProbeStart = nil self.PendingSale = nil
		self.Controller:Log("FARM][SELL", "Observed native sale: bubble amount decreased and actual balances subsequently increased")
	end
	if self.PendingSale and now > self.PendingSale.ExpiresAt then self.PendingSale = nil end
	self.LastBubbleAmount = amount
	local current = self.Tracker.Current
	if current then
		self.EmptySince = self.EmptySince or {}
		if current.EligibleCount > 0 then
			self.EmptySince[current.Key] = nil
			local failure = self.Mechanics.Failures["ISLAND:" .. current.Key]
			if failure and failure.Reason == "No eligible pickups observed" then self.Mechanics.Failures["ISLAND:" .. current.Key] = nil end
		else
			self.EmptySince[current.Key] = self.EmptySince[current.Key] or now
			if now - self.EmptySince[current.Key] >= self.Config.ISLAND_SETTINGS.EMPTY_ISLAND_CONFIRMATION_SECONDS
				and self.Mechanics:Available("ISLAND:" .. current.Key) then
				self.Mechanics:Failure("ISLAND:" .. current.Key, self.Config.ISLAND_SETTINGS.EMPTY_ISLAND_RETRY_SECONDS, "No eligible pickups observed")
			end
		end
	end
	if self.Controller.State == "RUNNING" then
		local raw = self.Reader:GetLiveProfile()
		local capacity = raw and self.Reader:_stat("GetBubbleStorage", raw, {})
		if self.Activity and self.Activity.Kind == "FARM" and self.Activity.Mode ~= "PICKUPS" and raw and raw.Bubble and type(raw.Bubble.Amount) == "number" and capacity and capacity > 0
			and raw.Bubble.Amount / capacity >= self.Config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO and self.Config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES then
			self.Controller.Scheduler:CancelActive("Bubble reached sell threshold") self.Mechanics:StopMovement()
		end
		self.Controller:_requestPlan(false)
	end
	self.Controller:_notify()
end

function FarmingCoordinator:StartObservations()
	if self.ObservationThread or not self.Config.FARMING_SETTINGS.AUTO_RESOURCE_FARM then return end
	self.ObservationThread = task.spawn(function()
		while not self.Destroyed do
			task.wait(self.Config.FARMING_SETTINGS.OBSERVATION_INTERVAL_SECONDS)
			if not self.Destroyed then self:Observe() end
		end
	end)
end

function FarmingCoordinator:Context(plan)
	local now = os.clock()
	local tracker, mechanics = self.Tracker, self.Mechanics
	local islands, areaRates = {}, {}
	for _, area in pairs(tracker.Areas) do
		area.InBackoff = not mechanics:Available("ISLAND:" .. area.Key)
		if area.Spawn then
			area.InBackoff = area.InBackoff or not mechanics:Available("TRAVEL:" .. area.Spawn:GetFullName())
			area.TravelSeconds = mechanics.TravelTimes and mechanics.TravelTimes[area.Spawn:GetFullName()]
		end
		table.insert(islands, area) areaRates[area.Key] = self.Metrics:Rates(area.Key, now)
	end
	local allowed, reason = mechanics:Guard()
	local canBlow, bubbleReason = mechanics:CanBlow()
	canBlow = canBlow and mechanics:Available("BLOW")
	local _, humanoid = tracker:Root()
	local raw = self.Reader:GetLiveProfile()
	local currentKey = tracker.Current and tracker.Current.Key or "UNKNOWN"
	local snapshot = self.Reader:GetSnapshot()
	local context = { Current = tracker.Current, Islands = islands, AreaRates = areaRates,
		SceneReady = tracker.LastZoneRefresh > -math.huge and tracker.Error == nil,
		Rates = self.Metrics:Rates(currentKey, now), Sells = mechanics:SellStations(), CanInteract = allowed,
		CanBlow = canBlow, CanTravel = now - mechanics.LastTravelAt >= self.Config.ISLAND_SETTINGS.TRAVEL_COOLDOWN_SECONDS,
		Blocker = reason or bubbleReason or tracker.Error, Now = now, ArrivedAt = tracker.ArrivedAt,
		WalkSpeed = humanoid and humanoid.WalkSpeed, UpgradeBackoff = {}, EffectiveUpgrades = {},
		BubbleProbePending = self.ProbeStart and raw and raw.Bubble and raw.Bubble.Amount > self.ProbeStart.Amount }
	for _, upgrade in ipairs((snapshot.AvailableProgression or {}).Upgrades or {}) do
		context.UpgradeBackoff[upgrade.Name] = not mechanics:Available("UPGRADE:" .. upgrade.Name)
		local enabled = upgrade.Kind == "Gum" and self.Config.BUBBLE_SETTINGS.AUTO_BUY_GUM
			or (upgrade.Kind == "Flavors" and self.Config.BUBBLE_SETTINGS.AUTO_BUY_FLAVORS)
		if raw and raw.Bubble and enabled and upgrade.Accessible and upgrade.OwnershipKnown and not upgrade.Owned then
			local cost = upgrade.Cost
			if cost and type(raw[cost.Currency]) == "number" and type(cost.Amount) == "number" and cost.Amount <= raw[cost.Currency]
				and cost.Amount <= self.Config.UPGRADE_SETTINGS.MAXIMUM_PURCHASE_COST then
				-- Project only the equipment field in a detached table; the received profile is never mutated.
				local projected = table.clone(raw) projected.Bubble = table.clone(raw.Bubble)
				projected.Bubble[upgrade.Kind == "Gum" and "Gum" or "Flavor"] = upgrade.Name
				context.EffectiveUpgrades[upgrade.Name] = { Capacity = self.Reader:_stat("GetBubbleStorage", projected, {}),
					Power = self.Reader:_stat("GetBubblePower", projected, {}) }
			end
		end
	end
	local currency = FarmingPolicy.Target(self.Config, snapshot, plan, context)
	context.Cluster = currency and tracker:Cluster(currency) or nil
	context.ActiveSweepPending = tracker.Sweep and tracker.Sweep.Started and next(tracker.Sweep.Pending) ~= nil
	-- A zero-yield completed trial must not be advertised as proven bubble income merely because time elapsed.
	if not self.SaleEvidence[currentKey] and context.Rates.BUBBLES then context.Rates.BUBBLES.Ready = false end
	return context
end

function FarmingCoordinator:Select(plan)
	local context = self:Context(plan)
	local decision = self.Controller.Brain:PlanFarming(self.Reader:GetSnapshot(), plan, context)
	self.Decision = decision
	local signature = decision.Kind .. ":" .. tostring(decision.Mode) .. ":" .. tostring(decision.Currency) .. ":" .. (decision.Island and decision.Island.Key or "")
	if signature ~= self.LastDecisionSignature or os.clock() - self.LastLogAt >= math.max(5, self.Config.DIAGNOSTIC_SETTINGS.MINIMUM_LOG_INTERVAL_SECONDS) then
		self.LastDecisionSignature, self.LastLogAt = signature, os.clock()
		self.Controller:Log("FARM][GOAL", tostring(decision.Goal) .. " | required=" .. tostring(decision.Currency) .. " | deficit=" .. tostring(decision.Deficit or "no fixed deficit"))
		for index, candidate in ipairs(decision.IslandCandidates) do
			if index > self.Config.DIAGNOSTIC_SETTINGS.MAXIMUM_LOG_ENTRIES then break end
			self.Controller:Log("FARM][ISLANDS", string.format("%s | %.2f %s/min | %s | overhead %.1fs | respawn %s", candidate.Key, candidate.PerMinute,
				candidate.Currency, candidate.Evidence, candidate.TravelSeconds, tostring(candidate.RespawnSeconds or "unknown")))
		end
		self.Controller:Log(decision.Kind == "WAIT" and "FARM][FALLBACK" or "FARM][DECISION", decision.Kind .. "/" .. tostring(decision.Mode) .. " | " .. decision.Reason)
		for mode, entry in pairs(context.Rates) do
			if entry.Ready then
				self.Controller:Log("FARM][EARNINGS", string.format("%s observed sample %.1fs | %.2f %s/min | external rewards can affect attribution",
					mode, entry.Seconds, entry.PerMinute[decision.Currency] or 0, tostring(decision.Currency)))
			end
		end
	end
	return decision
end

function FarmingCoordinator:_settle(token, seconds, tick)
	local deadline = os.clock() + seconds
	while not token:CheckCancelled() and os.clock() < deadline do
		if tick then tick() end
		task.wait(0.1)
	end
end

function FarmingCoordinator:_awaitCredit(before, token)
	local deadline = os.clock() + self.Config.FARMING_SETTINGS.EARNINGS_CONFIRMATION_TIMEOUT_SECONDS
	local after = self.Reader:ReadBalances()
	while not token:CheckCancelled() and os.clock() < deadline do
		for currency, value in pairs(after) do if before[currency] ~= nil and value > before[currency] then return after end end
		task.wait(0.1) after = self.Reader:ReadBalances()
	end
	return after
end

function FarmingCoordinator:_collection(decision, token)
	local cluster = decision.Cluster
	if not self.Config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS or not cluster then return { Verified = false, Reason = "Collection disabled or cluster unavailable" } end
	if self.Tracker.Sweep and self.Tracker.Sweep.Id == cluster.SweepId then self.Tracker.Sweep.Started = true end
	local before = self.Reader:ReadBalances()
	local beforeVisible = 0
	for _, record in ipairs(cluster.Records) do if record.Model.Parent then beforeVisible += 1 end end
	self.Controller:Log("FARM][BULK", string.format("Island=%s | total eligible=%d | cluster=%d | native radius=%.1f | method=NATIVE_RADIUS_CLUSTER_FALLBACK; no island-wide batch API",
		cluster.AreaKey, self.Tracker.Current and self.Tracker.Current.EligibleCount or 0, beforeVisible, cluster.Radius))
	self.Controller:Log("FARM][BULK", string.format("Sweep %d | %d/%d pending in frozen island set; new spawns enter the next sweep", cluster.SweepId, cluster.SweepRemaining, cluster.SweepTotal))
	local function allGone()
		for _, record in ipairs(cluster.Records) do if record.Model.Parent then return false end end
		return true
	end
	local tick = decision.Mode == "COMBINED" and function() self.Mechanics:Blow(token) end or nil
	local permitted, reason = self.Mechanics:Walk(cluster.Position, token, os.clock() + self.Config.FARMING_SETTINGS.ACTION_SLICE_SECONDS, tick, allGone)
	if token:CheckCancelled() then return nil end
	if permitted then self:_settle(token, self.Config.PICKUP_SETTINGS.COLLECTION_SETTLE_SECONDS, tick) end
	local disappeared = 0
	for _, record in ipairs(cluster.Records) do if not record.Model.Parent then disappeared += 1 end end
	if not permitted then
		self.Tracker:BackOff(cluster.Records, reason == "Slice ended" and self.Config.PICKUP_SETTINGS.COLLECTION_RETRY_SECONDS or self.Config.PICKUP_SETTINGS.UNREACHABLE_RETRY_SECONDS, reason)
	elseif disappeared == 0 then
		self.Tracker:BackOff(cluster.Records, self.Config.PICKUP_SETTINGS.COLLECTION_RETRY_SECONDS, "No disappearance observed")
	end
	local after = self:_awaitCredit(before, token)
	local gains = self.Metrics:ConfirmCycle(before, after, "Native collection cycle")
	self.Controller:Log("FARM][BULK", string.format("%d/%d models disappeared (not proof of credit) | %s", disappeared, beforeVisible, reason or "observed"))
	self.Controller:Log("FARM][EARNINGS", "before: " .. balancesText(before) .. " | after: " .. balancesText(after) .. " | " .. self.Metrics.LastConfirmation)
	self.Tracker:Refresh(self.Reader:GetSnapshot(), os.clock())
	return { Verified = next(gains) ~= nil, Disappeared = disappeared, Gains = gains, Reason = reason }
end

function FarmingCoordinator:_bubble(token)
	if not self.Config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES then return { Verified = false, Reason = "Blowing disabled" } end
	local raw = self.Reader:GetLiveProfile()
	local before = raw and raw.Bubble and raw.Bubble.Amount
	local maximum = before
	local beforeBalances = self.Reader:ReadBalances()
	local requests, deadline = 0, os.clock() + self.Config.FARMING_SETTINGS.ACTION_SLICE_SECONDS
	while not token:CheckCancelled() and os.clock() < deadline do
		local allowed, reason = self.Mechanics:CanBlow()
		if not allowed then self.Mechanics.LastBlocker = reason break end
		local live = self.Reader:GetLiveProfile()
		if live and live.Bubble and type(live.Bubble.Amount) == "number" then maximum = math.max(maximum or 0, live.Bubble.Amount) end
		local capacity = live and self.Reader:_stat("GetBubbleStorage", live, {})
		if live and live.Bubble and capacity and live.Bubble.Amount / capacity >= self.Config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO then break end
		if self.Mechanics:Blow(token) then requests += 1 end
		task.wait(0.1)
	end
	local live = self.Reader:GetLiveProfile()
	local after = live and live.Bubble and live.Bubble.Amount
	local afterBalances = self.Reader:ReadBalances()
	local income = false
	for currency, value in pairs(afterBalances) do if beforeBalances[currency] and value > beforeBalances[currency] then income = true end end
	local changed = type(before) == "number" and type(maximum) == "number" and maximum > before or income
	if income and self.Metrics.Active then self.SaleEvidence[self.Metrics.Active.Scope] = true end
	if requests > 0 and not changed and not token:CheckCancelled() then self.Mechanics:Failure("BLOW", 10, "No bubble growth confirmed") end
	self.Controller:Log("FARM][BUBBLE", "requests=" .. requests .. " | actual amount " .. tostring(before) .. " -> " .. tostring(after)
		.. " | " .. tostring(self.Mechanics.LastBlocker or "awaiting native sale for currency yield"))
	return { Verified = changed, Reason = self.Mechanics.LastBlocker }
end

function FarmingCoordinator:_sell(decision, token)
	local sell = decision.Sell
	if not self.Config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES or not sell then return { Verified = false, Reason = "Selling disabled" } end
	local raw = self.Reader:GetLiveProfile()
	local beforeAmount = raw and raw.Bubble and raw.Bubble.Amount
	local before = self.Reader:ReadBalances()
	local current = self.Tracker.Current
	local sameArea = current and current.World == sell.World and current.Name == sell.Area
	local permitted, reason
	if sameArea and sell.Distance <= self.Config.PICKUP_SETTINGS.MAXIMUM_ROUTE_DISTANCE_STUDS then
		permitted, reason = self.Mechanics:Walk(sell.Root.Position, token, os.clock() + self.Config.FARMING_SETTINGS.ACTION_SLICE_SECONDS)
	else
		self.Controller:Log("FARM][TRAVEL", "Native selling-station travel to " .. sell.Key .. " | currency=" .. sell.Currency .. " | multiplier=" .. sell.Multiplier)
		permitted, reason = self.Mechanics:Travel(sell.Root, sell.World, sell.Area, token)
	end
	if not permitted or token:CheckCancelled() then
		if not token:CheckCancelled() then self.Mechanics:Failure("SELL:" .. sell.Key, self.Config.BUBBLE_SETTINGS.SELL_RETRY_COOLDOWN_SECONDS, reason) end
		return { Verified = false, Reason = reason }
	end
	local deadline = os.clock() + self.Config.BUBBLE_SETTINGS.SELL_CONFIRMATION_TIMEOUT_SECONDS
	while not token:CheckCancelled() and os.clock() < deadline do
		local live = self.Reader:GetLiveProfile()
		local root = self.Tracker:Root()
		if not root or not sell.Root.Parent then break end
		local horizontal = ((root.Position - sell.Root.Position) * Vector3.new(1, 0, 1)).Magnitude
		if horizontal > sell.Root.Size.Y / 2 or math.abs(root.Position.Y - sell.Root.Position.Y) > 10 then
			self.Mechanics:StopMovement() reason = "Native sell activation range was not reached" break
		end
		if live and live.Bubble and type(beforeAmount) == "number" and live.Bubble.Amount < beforeAmount then
			local after = self:_awaitCredit(before, token)
			local gains = self.Metrics:ConfirmCycle(before, after, "Native bubble sale")
			local active = self.Metrics.Active
			if active and next(gains) then self.SaleEvidence[active.Scope] = true end
			self.ProbeStart = nil
			self.Controller:Log("FARM][SELL", string.format("Actual bubble amount %.0f -> %.0f | station multiplier %.2f | %s", beforeAmount, live.Bubble.Amount, sell.Multiplier, self.Metrics.LastConfirmation))
			self.Controller:Log("FARM][EARNINGS", "before: " .. balancesText(before) .. " | after: " .. balancesText(after))
			return { Verified = next(gains) ~= nil, BubbleReduced = true, Gains = gains }
		end
		task.wait(0.2)
	end
	if not token:CheckCancelled() then self.Mechanics:Failure("SELL:" .. sell.Key, self.Config.BUBBLE_SETTINGS.SELL_RETRY_COOLDOWN_SECONDS, reason or "Native sale not confirmed") end
	return { Verified = false, Reason = reason or "Native sale not confirmed" }
end

function FarmingCoordinator:Definition(decision, generation)
	if decision.Kind == "WAIT" then return nil end
	return { Id = "OC_GAMEPLAY", Priority = 10, Generation = generation,
		TimeoutSeconds = self.Config.FARMING_SETTINGS.ACTION_SLICE_SECONDS + self.Config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS
			+ self.Config.BUBBLE_SETTINGS.SELL_CONFIRMATION_TIMEOUT_SECONDS + self.Config.UPGRADE_SETTINGS.PURCHASE_CONFIRMATION_TIMEOUT_SECONDS + 5,
		CanRun = function() return not self.Destroyed and self.Controller.State == "RUNNING" and generation == self.Controller.Generation end,
		Execute = function(token)
			self.Activity = decision
			local scope = self.Tracker.Current and self.Tracker.Current.Key or "UNKNOWN"
			local beforeBalances = self.Reader:ReadBalances()
			if decision.Kind == "FARM" then
				self.Metrics:SetMode(decision.Mode, scope, beforeBalances, os.clock())
				if decision.Mode == "BUBBLES" and not self.ProbeStart then
					local raw = self.Reader:GetLiveProfile()
					self.ProbeStart = raw and raw.Bubble and { Amount = raw.Bubble.Amount, At = os.clock() } or nil
				end
			elseif decision.Kind ~= "SELL" then self.Metrics:SetMode(nil, scope, beforeBalances, os.clock()) end
			if decision.Kind == "TRAVEL" then
				local area = decision.Island
				self.Controller:Log("FARM][TRAVEL", "Request " .. area.Key .. " through native unlocked island Teleport | " .. decision.Reason)
				local success, reason, seconds = self.Mechanics:Travel(area.Spawn, area.World, area.Name, token)
				if success then
					self.Tracker:Refresh(self.Reader:GetSnapshot(), os.clock())
					local actual = self.Tracker.Current
					success = actual ~= nil and actual.Key == area.Key
					if success then self.Controller:Log("FARM][TRAVEL", "Arrival and island identity confirmed: " .. area.Key .. " | " .. tostring(seconds) .. "s") end
				end
				if not success and not token:CheckCancelled() then
					self.Mechanics:Failure("ISLAND:" .. area.Key, self.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS, reason or "Island identity uncertain")
					self.Controller:Log("FARM][TRAVEL", "Unconfirmed arrival: " .. area.Key .. " | " .. tostring(reason))
				end
				return { Verified = success, Reason = reason }
			elseif decision.Kind == "SELL" then return self:_sell(decision, token)
			elseif decision.Kind == "UPGRADE" then
				self.Controller:Log("UPGRADE", decision.Upgrade.Name .. " | " .. decision.Reason)
				local success, reason = self.Mechanics:Upgrade(decision.Upgrade, token)
				self.Controller:Log("UPGRADE", decision.Upgrade.Name .. " | " .. tostring(reason) .. " | verified=" .. tostring(success))
				if success then
					self.Metrics.Samples = {} self.SaleEvidence = {} self.ProbeStart = nil
					self.Controller.Brain.FarmingMemory = nil
				end
				return { Verified = success, Reason = reason }
			elseif decision.Mode == "BUBBLES" then return self:_bubble(token)
			else return self:_collection(decision, token) end
		end,
		IsComplete = function(result) return type(result) == "table" end,
	}
end

function FarmingCoordinator:Completed(status, result, reason)
	self.Mechanics:StopMovement()
	self.Activity = nil
	self.Metrics:Observe(self.Reader:ReadBalances(), os.clock())
	if status == "FAILED" then self.Controller:Log("FARM][ERROR", tostring(result))
	elseif result and not result.Verified and result.Reason then self.Controller:Log("FARM][FALLBACK", result.Reason)
	elseif status == "CANCELLED" then self.Controller:Log("FARM][CANCELLED", tostring(reason)) end
	self:Observe()
end

function FarmingCoordinator:Halt()
	self.Mechanics:StopMovement()
	self.Metrics:SetMode(nil, nil, self.Reader:ReadBalances(), os.clock())
	self.Activity = nil self.ProbeStart = nil self.PendingSale = nil self.EmptySince = {}
end

function FarmingCoordinator:GetStatus()
	local current = self.Tracker.Current
	return { Activity = self.Activity and (self.Activity.Mode or self.Activity.Kind), Decision = self.Decision,
		Area = current and current.Key, VisiblePickups = current and current.VisibleCount or 0,
		EligiblePickups = current and current.EligibleCount or 0, UnknownPickups = current and current.UnknownCount or 0,
		Disappeared = self.Tracker.Disappeared, ObservedSpawns = self.Tracker.ObservedSpawns,
		RespawnObservations = self.Tracker.RespawnObservations, Radius = self.Tracker.Range,
		Rates = self.Metrics:Rates(current and current.Key or "UNKNOWN", os.clock()),
		ConfirmedCycles = self.Metrics.ConfirmedCycles, LastConfirmation = self.Metrics.LastConfirmation,
		Error = self.Tracker.Error, CollectionMethod = "Native radius clusters; no genuine island-wide batch API found" }
end

function FarmingCoordinator:Destroy()
	self:Halt() self.Destroyed = true
	if self.ObservationThread then pcall(task.cancel, self.ObservationThread) end
	self.Tracker:Destroy()
end

return FarmingCoordinator

end

-- src/OCFoundation/FarmingPolicy.luau
factories["FarmingPolicy"] = function()
--!nonstrict
-- Pure decision policy used exclusively by OCBrain. Executors cannot choose their own activities.
local FarmingPolicy = {}
local function allowed(list, value) return #list == 0 or table.find(list, value) ~= nil end
local function reserve(config, currency)
	local field = ({ Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" })[currency]
	if currency == "Leaves26" then return config.FALL_EVENT_SETTINGS.LEAF_RESERVE end
	if currency == "RebirthShards26" then return config.FALL_EVENT_SETTINGS.REBIRTH_SHARD_RESERVE end
	return field and config.RESOURCE_SETTINGS[field] or 0
end
local function rate(context, mode, currency)
	local entry = context.Rates[mode]
	return entry and entry.Ready and (entry.PerMinute[currency] or 0) or nil
end

function FarmingPolicy.Target(config, snapshot, plan, context)
	local candidates = {}
	if plan.Objective then table.insert(candidates, plan.Objective) end
	for _, candidate in ipairs(plan.Candidates or {}) do if candidate ~= plan.Objective then table.insert(candidates, candidate) end end
	for _, candidate in ipairs(candidates) do
		local cost = candidate.Metadata and candidate.Metadata.Cost
		if cost and cost.Type == "Currency" and type(cost.Amount) == "number" and snapshot.Balances[cost.Currency] ~= nil
			and allowed(config.PICKUP_SETTINGS.FARM_CURRENCY_TYPES, cost.Currency) then
			local required = cost.Amount + reserve(config, cost.Currency)
			if candidate.Metadata.Upgrade then required = cost.Amount / config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION + reserve(config, cost.Currency) end
			if snapshot.Balances[cost.Currency] < required then
				return cost.Currency, candidate, required - snapshot.Balances[cost.Currency]
			end
		end
	end
	for _, currency in ipairs(config.FARMING_SETTINGS.CURRENCY_PRIORITIES) do
		if not allowed(config.PICKUP_SETTINGS.FARM_CURRENCY_TYPES, currency) then continue end
		for _, area in ipairs(context.Islands or {}) do if area.Unlocked and area.Currencies[currency] then return currency, plan.Objective, nil end end
		for _, sell in ipairs(context.Sells or {}) do if sell.Currency == currency then return currency, plan.Objective, nil end end
	end
	return nil, plan.Objective, nil
end

function FarmingPolicy.Decide(config, snapshot, plan, context, memory)
	local decision = { Kind = "WAIT", Reason = "Waiting for supported farming data", IslandCandidates = {}, Currency = nil }
	if not config.FARMING_SETTINGS.AUTO_RESOURCE_FARM or not snapshot.Ready or not config.GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS then
		decision.Reason = "Farming disabled or real account/planner not ready" return decision
	end
	if context.SceneReady == false then decision.Reason = context.Blocker or "Waiting for actual zone inspection before selecting a farming activity" return decision end
	local currency, goal, deficit = FarmingPolicy.Target(config, snapshot, plan, context)
	decision.Currency, decision.Goal, decision.Deficit = currency, goal and goal.Title, deficit
	if not currency then decision.Reason = "No allowed goal currency with an accessible earning source" return decision end
	local current = context.Current
	local bestSell, bestSellScore
	for _, sell in ipairs(context.Sells or {}) do
		if sell.Currency ~= currency then continue end
		local walking = current and sell.World == current.World and sell.Area == current.Name and sell.Distance <= config.PICKUP_SETTINGS.MAXIMUM_ROUTE_DISTANCE_STUDS
		local canTravel = config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND and context.CanTravel
		if not walking and not canTravel then continue end
		local travel = walking and sell.Distance / math.max(1, context.WalkSpeed or 16)
			or sell.TravelSeconds or config.ISLAND_SETTINGS.UNMEASURED_TRAVEL_OVERHEAD_SECONDS
		local bubble = snapshot.Bubble
		local fillSeconds = bubble.Capacity and bubble.PowerPerBlow and bubble.PowerPerBlow > 0
			and bubble.Capacity / bubble.PowerPerBlow * config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS or nil
		local score = sell.Multiplier / math.max(1, (fillSeconds or 60) + travel + 2)
		if not bestSell or score > bestSellScore then bestSell, bestSellScore = sell, score end
	end
	local bubble = snapshot.Bubble or {}
	local full = bubble.Amount and bubble.Capacity and bubble.Capacity > 0 and bubble.Amount / bubble.Capacity >= config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO
	-- Sell an existing full bubble even when its station pays a different resource; do not value that payout as target currency.
	if full and config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES and context.CanInteract then
		local sell = bestSell
		if not sell then
			for _, candidate in ipairs(context.Sells or {}) do
				local sameArea = current and candidate.World == current.World and candidate.Area == current.Name and candidate.Distance <= config.PICKUP_SETTINGS.MAXIMUM_ROUTE_DISTANCE_STUDS
				if sameArea or (config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND and context.CanTravel) then
					if not sell or candidate.Distance < sell.Distance then sell = candidate end
				end
			end
		end
		if sell then decision.Kind = "SELL" decision.Sell = sell decision.Reason = "Bubble reached sell threshold; verify native sale before producing more" return decision end
	end
	local bestIsland, currentScore = nil, nil
	if config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS then
		for _, area in ipairs(context.Islands or {}) do
			if not area.Unlocked or not allowed(config.ISLAND_SETTINGS.SELECTED_ISLANDS, area.Name)
				or not allowed(config.BRAIN_SETTINGS.SELECTED_WORLDS, area.World) or not area.Currencies[currency] or area.InBackoff then continue end
			if area ~= current and (not area.Spawn or not config.ISLAND_SETTINGS.AUTO_SELECT_BEST_ISLAND or not config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND) then continue end
			local rates = context.AreaRates[area.Key] or {}
			local observed = rates.PICKUPS
			local measured = observed and observed.Ready and (observed.PerMinute[currency] or 0) or nil
			local cycle = area.RespawnSeconds or config.ISLAND_SETTINGS.UNMEASURED_COLLECTION_CYCLE_SECONDS
			local overhead = area == current and 0 or area.TravelSeconds or config.ISLAND_SETTINGS.UNMEASURED_TRAVEL_OVERHEAD_SECONDS
			local estimate = area.Expected[currency] and area.Expected[currency] * 60 / math.max(1, cycle) or nil
			local value = measured ~= nil and measured or estimate
			if value == nil then continue end
			local net = value * cycle / math.max(1, cycle + overhead)
			if area == current and (area.Available[currency] or 0) == 0 then net = 0 end
			local entry = { Key = area.Key, Name = area.Name, Currency = currency, PerMinute = net,
				Evidence = measured ~= nil and "OBSERVED" or "ESTIMATE: definitions, actual stat multiplier, unknown availability/respawn", Area = area,
				TravelSeconds = overhead, RespawnSeconds = area.RespawnSeconds }
			table.insert(decision.IslandCandidates, entry)
			if area == current then currentScore = net end
			if not bestIsland or net > bestIsland.PerMinute or (net == bestIsland.PerMinute and area.Key < bestIsland.Key) then bestIsland = entry end
		end
	end
	table.sort(decision.IslandCandidates, function(a, b) return a.PerMinute > b.PerMinute end)
	if bestIsland and current and bestIsland.Area ~= current and current.Currencies[currency] and not current.InBackoff then
		if context.Now - (context.ArrivedAt or 0) < config.ISLAND_SETTINGS.MIN_ISLAND_DWELL_SECONDS
			or ((currentScore or 0) > 0 and bestIsland.PerMinute <= currentScore * (1 + config.ISLAND_SETTINGS.MIN_ISLAND_GAIN_ADVANTAGE_PERCENT / 100)) then
			for _, entry in ipairs(decision.IslandCandidates) do if entry.Area == current then bestIsland = entry break end end
		end
	end
	local cluster = context.Cluster
	local pickupReady = config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS and cluster ~= nil and context.CanInteract
	local bubbleReady = config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES and config.BUBBLE_SETTINGS.AUTO_SELL_BUBBLES and bestSell ~= nil and context.CanBlow and not full
	local choices = {}
	if pickupReady then table.insert(choices, "PICKUPS") end
	if bubbleReady then table.insert(choices, "BUBBLES") end
	if pickupReady and bubbleReady and config.BUBBLE_SETTINGS.ENABLE_SIMULTANEOUS_BLOWING then table.insert(choices, "COMBINED") end
	if not config.FARMING_SETTINGS.AUTO_FARM_FALLBACK and memory.Mode and not table.find(choices, memory.Mode) then
		decision.Reason = "Preferred activity unavailable; fallback is disabled" return decision
	end
	local mode, modeScore
	if config.FARMING_SETTINGS.ENABLE_EFFICIENCY_COMPARISON then
		for _, candidate in ipairs(choices) do
			local measured = rate(context, candidate, currency)
			if measured and (not modeScore or measured > modeScore) then mode, modeScore = candidate, measured end
		end
	elseif table.find(choices, "COMBINED") then
		mode = "COMBINED"
	end
	-- Unknown modes get bounded probes, rather than fabricated income rates.
	local untested, oldestTest = nil, math.huge
	for _, candidate in ipairs(choices) do
		local lastTest = memory.LastTest[candidate] or -math.huge
		if candidate ~= memory.Mode and (not memory.Mode or context.Now - memory.StartedAt >= config.FARMING_SETTINGS.MINIMUM_ACTIVITY_HOLD_SECONDS)
			and context.Now - lastTest >= config.FARMING_SETTINGS.EXPLORATION_INTERVAL_SECONDS and lastTest < oldestTest then
			untested, oldestTest = candidate, lastTest
		end
	end
	if config.FARMING_SETTINGS.ENABLE_EFFICIENCY_COMPARISON and untested then mode = untested modeScore = nil end
	mode = mode or choices[1]
	if memory.Mode and table.find(choices, memory.Mode) then
		local age = context.Now - memory.StartedAt
		local currentRate = rate(context, memory.Mode, currency)
		if not config.FARMING_SETTINGS.ENABLE_ACTIVITY_SWITCHING or age < config.FARMING_SETTINGS.MINIMUM_ACTIVITY_HOLD_SECONDS
			or (modeScore and currentRate and modeScore <= currentRate * (1 + config.FARMING_SETTINGS.ACTIVITY_SWITCH_GAIN_RATIO)) then mode = memory.Mode end
		if memory.Mode == "BUBBLES" and context.BubbleProbePending and age < config.FARMING_SETTINGS.BUBBLE_PROBE_TIMEOUT_SECONDS then mode = "BUBBLES" end
	end
	if bestIsland and bestIsland.Area ~= current and bestIsland.PerMinute > 0 and context.CanTravel and context.CanInteract
		and not (context.ActiveSweepPending and pickupReady) then
		local bubbleIncome = rate(context, "BUBBLES", currency)
		if not bubbleReady or not bubbleIncome or bestIsland.PerMinute > bubbleIncome * (1 + config.FARMING_SETTINGS.ACTIVITY_SWITCH_GAIN_RATIO) then
			decision.Kind = "TRAVEL" decision.Island = bestIsland.Area
			decision.Reason = string.format("Best eligible %s island: %s; %.2f/min %s after %.1fs travel overhead", currency, bestIsland.Name, bestIsland.PerMinute, bestIsland.Evidence, bestIsland.TravelSeconds)
			return decision
		end
	end
	if not mode then decision.Reason = context.Blocker or "No reachable relevant pickups or useful bubble selling route" return decision end
	decision.Kind, decision.Mode, decision.Cluster, decision.Sell = "FARM", mode, cluster, bestSell
	decision.Reason = modeScore and string.format("Observed %.2f %s/min supports the current goal", modeScore, currency)
		or "Bounded " .. mode .. " trial; observed balances will establish earning efficiency"
	local upgrades = config.UPGRADE_SETTINGS
	if upgrades.ENABLE_SMART_UPGRADES and config.BRAIN_SETTINGS.ENABLE_EARNING_RECOMMENDATIONS and config.BUBBLE_SETTINGS.ENABLE_BUBBLE_RECOMMENDATIONS then
		local income = rate(context, "BUBBLES", currency)
		local orderedUpgrades = table.clone((snapshot.AvailableProgression or {}).Upgrades or {})
		table.sort(orderedUpgrades, function(a, b)
			if a.Owned ~= b.Owned then return a.Owned == true end
			local left = a.Cost and a.Cost.Amount or math.huge
			local right = b.Cost and b.Cost.Amount or math.huge
			if left == right then return a.Name < b.Name end
			return left < right
		end)
		for _, upgrade in ipairs(orderedUpgrades) do
			local currentStat = upgrade.Kind == "Gum" and bubble.BaseCapacity or bubble.BaseOutput
			local capacityAllowed = upgrade.Kind == "Gum" and upgrades.ENABLE_CAPACITY_UPGRADES
			local flavorAllowed = upgrade.Kind == "Flavors" and upgrades.ENABLE_FLAVOR_UPGRADES
			if not upgrade.Accessible or not upgrade.OwnershipKnown or not currentStat or currentStat <= 0 or not upgrade.BaseStat
				or not (capacityAllowed or flavorAllowed) or not allowed(upgrades.SELECTED_UPGRADES, upgrade.Name) or context.UpgradeBackoff[upgrade.Name] then continue end
			local gain = upgrade.BaseStat / currentStat - 1
			if gain < config.BRAIN_SETTINGS.MINIMUM_UPGRADE_GAIN_RATIO then continue end
			local gumBottleneck = bubble.Capacity and bubble.PowerPerBlow and bubble.PowerPerBlow > 0
				and bubble.Capacity / bubble.PowerPerBlow < config.BRAIN_SETTINGS.MINIMUM_BLOWS_PER_FILL
			if upgrade.Kind == "Gum" and not gumBottleneck then continue end
			if upgrade.Owned and upgrades.AUTO_EQUIP_OWNED_UPGRADES then
				decision.Kind, decision.Upgrade = "UPGRADE", table.clone(upgrade)
				decision.Reason = "Use a verified better owned bubble upgrade without spending" return decision
			end
			local enabled = upgrade.Kind == "Gum" and config.BUBBLE_SETTINGS.AUTO_BUY_GUM or (upgrade.Kind == "Flavors" and config.BUBBLE_SETTINGS.AUTO_BUY_FLAVORS)
			if upgrade.Owned or not enabled or mode == "PICKUPS" or not income or income <= 0 then continue end
			local cost = upgrade.Cost
			if not cost or cost.Currency ~= currency or type(cost.Amount) ~= "number" or cost.Amount < 0 then continue end
			local funds = snapshot.Balances[cost.Currency]
			local goalReserve = 0
			if upgrades.ENABLE_GOAL_RESERVATION then
				for _, reservedGoal in ipairs({ plan.Objective, goal }) do
					local goalCost = reservedGoal and reservedGoal.Metadata and reservedGoal.Metadata.Cost
					if goalCost and not reservedGoal.Metadata.Upgrade and goalCost.Currency == cost.Currency then
						goalReserve = math.max(goalReserve, goalCost.Amount or 0)
					end
				end
			end
			local reserveAmount = reserve(config, cost.Currency)
			local available = math.max(0, (funds or 0) - reserveAmount - goalReserve)
			local projection = context.EffectiveUpgrades and context.EffectiveUpgrades[upgrade.Name]
			if not projection or not projection.Capacity or not projection.Power or projection.Power <= 0 or not bubble.Capacity
				or not bubble.PowerPerBlow or bubble.PowerPerBlow <= 0 then continue end
			local fill = bubble.Capacity / bubble.PowerPerBlow * config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS
			local projectedFill = projection.Capacity / projection.Power * config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS
			local overhead = bestSell and (bestSell.TravelSeconds or math.min(config.ISLAND_SETTINGS.UNMEASURED_TRAVEL_OVERHEAD_SECONDS,
				bestSell.Distance / math.max(1, context.WalkSpeed or 16))) or config.ISLAND_SETTINGS.UNMEASURED_TRAVEL_OVERHEAD_SECONDS
			overhead += 2 -- Native Activation's observed sell interval.
			local rateGain = projection.Capacity / bubble.Capacity * (fill + overhead) / math.max(0.1, projectedFill + overhead) - 1
			-- Discount projected gain: catalog stat simulation is a model, not a verified new earning rate.
			local incremental = income / 60 * math.max(0, rateGain) * 0.5
			local payback = incremental > 0 and cost.Amount / incremental or math.huge
			if cost.Amount <= available * config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION and cost.Amount <= upgrades.MAXIMUM_PURCHASE_COST
				and payback <= upgrades.MAXIMUM_PAYBACK_SECONDS then
				decision.Kind, decision.Upgrade = "UPGRADE", table.clone(upgrade)
				decision.Upgrade.Reserve, decision.Upgrade.GoalReserve = reserveAmount, goalReserve
				decision.Reason = string.format("Verified %s improvement %.0f%%; conservative estimated payback %.1fs from observed bubble income", upgrade.Kind, gain * 100, payback)
				return decision
			end
		end
	end
	return decision
end

return FarmingPolicy

end

-- src/OCFoundation/GameMechanics.luau
factories["GameMechanics"] = function()
--!nonstrict
-- Only native commands inspected in HUD, WorldMap and GumShop. No pickup remote calls.
local GameMechanics = {}
GameMechanics.__index = GameMechanics
local CollectionService = game:GetService("CollectionService")

function GameMechanics.new(config, reader, tracker, player)
	return setmetatable({ Config = config, Reader = reader, Tracker = tracker, Player = player,
		LastBlowAt = -math.huge, LastTravelAt = -math.huge, Failures = {}, PathThread = nil }, GameMechanics)
end

function GameMechanics:Guard()
	local root, humanoid = self.Tracker:Root()
	if not root then return false, "Character is not alive" end
	local plaza = self.Reader:_dependency("IsTradingPlaza")
	local frames = self.Reader:_dependency("GuiFrame")
	local rods = self.Reader:_dependency("FishingPlayerRods")
	if not plaza or not frames or not rods then return false, "Interaction guard modules are not ready" end
	local ok, reason = pcall(function()
		if plaza() then return "Trading plaza is active" end
		if self.Player:GetAttribute("InRace") then return "An island race owns movement" end
		if rods:GetRodComponent(self.Player) ~= nil then return "A fishing rod is active" end
		local gui = self.Player:FindFirstChild("PlayerGui")
		local screen = gui and gui:FindFirstChild("ScreenGui")
		if not gui or not screen then return "Game ScreenGui is unavailable" end
		if gui:FindFirstChild("Intro") or gui:FindFirstChild("TransitionGui") then return "Intro or transition is active" end
		local trading = screen:FindFirstChild("Trading")
		if trading and trading.Visible then return "Trading is active" end
		if screen:FindFirstChild("Prompt") or frames:IsAnyOpen() then return "A game prompt or frame is open" end
		return nil
	end)
	if not ok then return false, "Interaction guards failed: " .. tostring(reason) end
	if reason then return false, reason end
	return true, nil, root, humanoid
end

function GameMechanics:CanBlow()
	if not self.Config.BUBBLE_SETTINGS.AUTO_BLOW_BUBBLES then return false, "Bubble blowing is disabled" end
	local allowed, reason = self:Guard()
	if not allowed then return false, reason end
	local raw = self.Reader:GetLiveProfile()
	if not raw or type(raw.Bubble) ~= "table" or type(raw.Settings) ~= "table" then return false, "Bubble profile is unavailable" end
	if raw.Settings["Bubble Lock"] == true then return false, "Bubble Lock is enabled" end
	local effects = self.Reader:_dependency("PhysicalItem")
	if not effects then return false, "PhysicalItem guard is unavailable" end
	if effects.IsGiftInRange then return false, "Gift interaction is active" end
	local screen = self.Player.PlayerGui.ScreenGui
	local hud, race = screen:FindFirstChild("HUD"), screen:FindFirstChild("IslandRace")
	if not ((hud and hud.Visible) or (race and race.Visible)) then return false, "Bubble HUD is hidden" end
	local capacity = self.Reader:_stat("GetBubbleStorage", raw, {})
	if type(raw.Bubble.Amount) ~= "number" or not capacity then return false, "Actual bubble capacity is unavailable" end
	if raw.Bubble.Amount >= capacity and not (raw.Passes and raw.Passes["Infinity Gum"]) then return false, "Bubble is full" end
	return true
end

function GameMechanics:Blow(token)
	if token:CheckCancelled() then return false end
	if os.clock() - self.LastBlowAt < self.Config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS then return false end
	local permitted, reason = self:CanBlow()
	if not permitted then self.LastBlocker = reason return false end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then self.LastBlocker = "Native Remote module unavailable" return false end
	self.LastBlowAt = os.clock()
	remote:FireServer("BlowBubble")
	self.LastBlocker = nil
	return true
end

function GameMechanics:Failure(key, seconds, reason)
	self.Failures[key] = { Until = os.clock() + seconds, Reason = reason }
end

function GameMechanics:Available(key)
	local failed = self.Failures[key]
	return not failed or os.clock() >= failed.Until
end

function GameMechanics:Unlocked(world, area)
	local raw = self.Reader:GetLiveProfile()
	return raw and type(raw.WorldsUnlocked) == "table" and raw.WorldsUnlocked[world] ~= nil
		and (world == area or (type(raw.AreasUnlocked) == "table" and raw.AreasUnlocked[area] ~= nil)) or false
end

function GameMechanics:SellStations()
	local result, root = {}, self.Tracker:Root()
	if not root then return result end
	local worlds = workspace:FindFirstChild("Worlds")
	for _, model in ipairs(CollectionService:GetTagged("Activation")) do
		local stationRoot = model:FindFirstChild("Root")
		if model.Name ~= "Sell" or not model:IsDescendantOf(workspace) or not stationRoot or not stationRoot:IsA("BasePart") then continue end
		local node, world, area = model, nil, nil
		while node and node ~= workspace do
			if node.Parent and node.Parent.Name == "Islands" then area = node.Name end
			if node.Parent == worlds then world = node.Name end
			node = node.Parent
		end
		area = area or world
		-- Match the locations used by native HUD.findBestSell; nested VIP/event facilities have unverified access rules.
		local worldRoot = worlds and worlds:FindFirstChild(world or "")
		local islandRoot = worldRoot and worldRoot:FindFirstChild("Islands")
		local island = islandRoot and islandRoot:FindFirstChild(area or "")
		local islandModel = island and island:FindFirstChild("Island")
		if model.Parent ~= worldRoot and model.Parent ~= islandModel then continue end
		if not world or not self:Unlocked(world, area) or not self:Available("SELL:" .. model:GetFullName()) then continue end
		local multiplier = model:GetAttribute("Multiplier") or 1 -- Verified native HUD defaults.
		local currency = model:GetAttribute("Currency") or "Coins"
		if type(multiplier) ~= "number" or multiplier <= 0 or type(currency) ~= "string" then continue end
		self.Reader:RegisterCurrency(currency)
		table.insert(result, { Model = model, Root = stationRoot, Key = model:GetFullName(), World = world, Area = area,
			Currency = currency, Multiplier = multiplier, Distance = (stationRoot.Position - root.Position).Magnitude,
			TravelSeconds = self.TravelTimes and self.TravelTimes[stationRoot:GetFullName()] })
	end
	return result
end

function GameMechanics:Travel(destination, world, area, token)
	local permitted, reason = self:Guard()
	if not permitted then return false, reason end
	if token:CheckCancelled() then return false, "Cancelled" end
	if not self.Config.ISLAND_SETTINGS.AUTO_TRAVEL_BEST_ISLAND then return false, "Supported teleport travel is disabled" end
	if not destination or not destination.Parent or not destination:IsA("BasePart") or not destination:IsDescendantOf(workspace)
		or not self:Unlocked(world, area) then return false, "Destination is unavailable or locked" end
	local path = destination:GetFullName()
	if not self:Available("TRAVEL:" .. path) then return false, "Destination travel is in backoff" end
	if os.clock() - self.LastTravelAt < self.Config.ISLAND_SETTINGS.TRAVEL_COOLDOWN_SECONDS then return false, "Travel cooldown" end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then return false, "Native Remote module unavailable" end
	local started = os.clock()
	self.LastTravelAt = started
	remote:FireServer("Teleport", path)
	local arrivedAt
	while not token:CheckCancelled() and os.clock() - started < self.Config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS do
		local root = self.Tracker:Root()
		if root and destination.Parent and (root.Position - destination.Position).Magnitude <= self.Config.ISLAND_SETTINGS.ARRIVAL_DISTANCE_STUDS then
			arrivedAt = arrivedAt or os.clock()
			if os.clock() - arrivedAt >= 0.4 then
				local seconds = os.clock() - started
				self.TravelTimes = self.TravelTimes or {} self.TravelTimes[path] = seconds
				return true, "Character arrival confirmed", seconds
			end
		else arrivedAt = nil end
		task.wait(0.1)
	end
	if not token:CheckCancelled() then self:Failure("TRAVEL:" .. path, self.Config.ISLAND_SETTINGS.TRAVEL_RETRY_COOLDOWN_SECONDS, "Arrival was not confirmed") end
	return false, token:CheckCancelled() and "Cancelled" or "Arrival was not confirmed"
end

function GameMechanics:StopMovement()
	if self.PathThread then pcall(task.cancel, self.PathThread) self.PathThread = nil end
	local lease = self.MovementLease
	self.MovementLease = nil
	if lease and lease.Root.Parent then
		pcall(function() lease.Humanoid:MoveTo(lease.Root.Position) lease.Humanoid:Move(Vector3.zero) end)
	end
end

function GameMechanics:Walk(point, token, deadline, tick, finished)
	local permitted, reason, root, humanoid = self:Guard()
	if not permitted then return false, reason end
	local settings = self.Config.PICKUP_SETTINGS
	local start = root.Position
	if (point - start).Magnitude <= 2 then return true, "Already in range" end
	if math.abs(point.Y - start.Y) > settings.MAXIMUM_VERTICAL_DIFFERENCE_STUDS then return false, "Destination is outside current island height" end
	local path = game:GetService("PathfindingService"):CreatePath({ AgentRadius = 2, AgentHeight = 5, AgentCanJump = true, WaypointSpacing = 6 })
	local computed, computeError
	self.PathThread = task.spawn(function()
		local success, message = pcall(function() path:ComputeAsync(start, point) end)
		computed, computeError = success, message
	end)
	local computeDeadline = math.min(deadline, os.clock() + settings.PATH_TIMEOUT_SECONDS)
	while computed == nil and not token:CheckCancelled() and os.clock() < computeDeadline do task.wait(0.1) end
	if self.PathThread then pcall(task.cancel, self.PathThread) self.PathThread = nil end
	if token:CheckCancelled() then path:Destroy() return false, "Cancelled" end
	if computed ~= true or path.Status ~= Enum.PathStatus.Success then path:Destroy() return false, "No supported path: " .. tostring(computeError) end
	local waypoints = path:GetWaypoints()
	local length, previous = 0, start
	for _, waypoint in ipairs(waypoints) do
		length += (waypoint.Position - previous).Magnitude previous = waypoint.Position
		if math.abs(waypoint.Position.Y - start.Y) > settings.MAXIMUM_VERTICAL_DIFFERENCE_STUDS then path:Destroy() return false, "Path leaves current island height" end
	end
	if length > settings.MAXIMUM_ROUTE_DISTANCE_STUDS or length > math.max(8, (point - start).Magnitude * settings.MAXIMUM_PATH_DETOUR_RATIO) then
		path:Destroy() return false, "Path requires excessive travel" end
	local blocked
	local connection = path.Blocked:Connect(function(index) blocked = index end)
	local result, message = true, "Cluster reached"
	for index, waypoint in ipairs(waypoints) do
		if index == 1 then continue end
		if finished and finished() then break end
		if token:CheckCancelled() or os.clock() >= deadline then result, message = false, "Slice ended" break end
		if waypoint.Action == Enum.PathWaypointAction.Jump then humanoid.Jump = true end
		self.MovementLease = { Root = root, Humanoid = humanoid }
		humanoid:MoveTo(waypoint.Position)
		local waypointDeadline = math.min(deadline, os.clock() + settings.PATH_TIMEOUT_SECONDS)
		while not token:CheckCancelled() and os.clock() < waypointDeadline do
			local liveRoot = self.Tracker:Root()
			local active, blockReason = self:Guard()
			if not liveRoot or not active then result, message = false, blockReason or "Character unavailable" break end
			if blocked and blocked >= index then result, message = false, "Path was blocked" break end
			if (liveRoot.Position - waypoint.Position).Magnitude <= 3 then break end
			if finished and finished() then break end
			if tick then tick() end
			task.wait(0.1)
		end
		if not result then break end
		local liveRoot = self.Tracker:Root()
		if token:CheckCancelled() then result, message = false, "Cancelled" break end
		if not (finished and finished()) and (not liveRoot or (liveRoot.Position - waypoint.Position).Magnitude > 3) then
			result, message = false, os.clock() >= deadline and "Slice ended" or "Waypoint stalled" break
		end
	end
	connection:Disconnect() path:Destroy()
	self:StopMovement()
	return result, message
end

function GameMechanics:Upgrade(upgrade, token)
	if token:CheckCancelled() then return false, "Cancelled" end
	local permitted, reason = self:Guard()
	if not permitted then return false, reason end
	local config, raw = self.Config, self.Reader:GetLiveProfile()
	if not config.FARMING_SETTINGS.AUTO_RESOURCE_FARM or not config.UPGRADE_SETTINGS.ENABLE_SMART_UPGRADES then return false, "Upgrade automation disabled" end
	if upgrade.Kind == "Gum" and not config.UPGRADE_SETTINGS.ENABLE_CAPACITY_UPGRADES then return false, "Capacity upgrades disabled" end
	if upgrade.Kind == "Flavors" and not config.UPGRADE_SETTINGS.ENABLE_FLAVOR_UPGRADES then return false, "Flavor upgrades disabled" end
	if not raw then return false, "No real account profile" end
	if not self:Available("UPGRADE:" .. upgrade.Name) then return false, "Upgrade is in backoff" end
	local definitions = self.Reader:_dependency(upgrade.Kind)
	local definition = definitions and definitions[upgrade.Name]
	if not definition or type(definition.Cost) ~= "table" or definition.Cost.Type ~= "Currency" then return false, "Verified nonpremium definition unavailable" end
	if definition.Area and not ((raw.AreasUnlocked and raw.AreasUnlocked[definition.Area] ~= nil) or (raw.WorldsUnlocked and raw.WorldsUnlocked[definition.Area] ~= nil)) then
		return false, "Upgrade area is locked" end
	local currentOwned = raw[upgrade.Kind] and raw[upgrade.Kind][upgrade.Name] ~= nil
	local command
	if currentOwned then
		if not config.UPGRADE_SETTINGS.AUTO_EQUIP_OWNED_UPGRADES then return false, "Owned upgrade equip disabled" end
		command = upgrade.Kind == "Gum" and "UpdateStorage" or "UpdateFlavor"
	else
		local enabled = upgrade.Kind == "Gum" and config.BUBBLE_SETTINGS.AUTO_BUY_GUM or (upgrade.Kind == "Flavors" and config.BUBBLE_SETTINGS.AUTO_BUY_FLAVORS)
		if not enabled then return false, "Purchase disabled" end
		local cost = definition.Cost
		local funds = raw[cost.Currency]
		if type(funds) ~= "number" or type(cost.Amount) ~= "number" or cost.Amount < 0 then return false, "Actual funds or cost unknown" end
		local spendable = math.max(0, funds - (upgrade.Reserve or 0) - (upgrade.GoalReserve or 0))
		if cost.Amount > config.UPGRADE_SETTINGS.MAXIMUM_PURCHASE_COST or cost.Amount > spendable * config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION then
			return false, "Actual funds no longer meet goal reserve and purchase budget" end
		command = "GumShopPurchase"
	end
	local remote = self.Reader:_dependency("Remote")
	if not remote or type(remote.FireServer) ~= "function" then return false, "Native Remote unavailable" end
	self:Failure("UPGRADE:" .. upgrade.Name, config.UPGRADE_SETTINGS.PURCHASE_RETRY_COOLDOWN_SECONDS, "Awaiting ownership/equipment confirmation")
	remote:FireServer(command, upgrade.Name)
	local deadline = os.clock() + config.UPGRADE_SETTINGS.PURCHASE_CONFIRMATION_TIMEOUT_SECONDS
	while not token:CheckCancelled() and os.clock() < deadline do
		local live = self.Reader:GetLiveProfile()
		if live then
			local owned = live[upgrade.Kind] and live[upgrade.Kind][upgrade.Name] ~= nil
			local equipped = live.Bubble and live.Bubble[upgrade.Kind == "Gum" and "Gum" or "Flavor"] == upgrade.Name
			if (not currentOwned and owned) or (currentOwned and equipped) then return true, currentOwned and "Actual equipped upgrade changed" or "Actual ownership received" end
		end
		task.wait(0.2)
	end
	return false, token:CheckCancelled() and "Cancelled" or "Ownership/equipment change was not confirmed"
end

return GameMechanics

end

-- src/OCFoundation/OCBrain.luau
factories["OCBrain"] = function()
--!nonstrict
-- Pure recommendation engine. It never invokes remotes, purchases, or movement.
local OCBrain = {}
local FarmingPolicy = requireOC("FarmingPolicy")
OCBrain.__index = OCBrain

local function countEntries(map)
	if type(map) ~= "table" then return nil end
	local count = 0
	for _ in pairs(map) do count += 1 end
	return count
end

local function reserveFor(config, currency)
	local fields = { Coins = "COIN_RESERVE", Gems = "GEM_RESERVE", Tickets = "TICKET_RESERVE", Pearls = "PEARL_RESERVE" }
	return fields[currency] and config.RESOURCE_SETTINGS[fields[currency]] or 0
end

function OCBrain.new(config)
	return setmetatable({ Config = config, Previous = nil, SelectedAt = 0 }, OCBrain)
end

function OCBrain:Reset()
	self.Previous = nil
	self.SelectedAt = 0
	self.FarmingMemory = { Mode = nil, StartedAt = 0, LastTest = {} }
end

function OCBrain:PlanFarming(snapshot, plan, context)
	self.FarmingMemory = self.FarmingMemory or { Mode = nil, StartedAt = 0, LastTest = {} }
	local result = FarmingPolicy.Decide(self.Config, snapshot, plan, context, self.FarmingMemory)
	if result.Kind == "FARM" and result.Mode ~= self.FarmingMemory.Mode then
		self.FarmingMemory.Mode, self.FarmingMemory.StartedAt = result.Mode, context.Now
		self.FarmingMemory.LastTest[result.Mode] = context.Now
	end
	return result
end

function OCBrain:Classify(snapshot)
	if not snapshot.Ready then return "UNDETERMINED", "No real player profile is available." end
	local worlds = countEntries(snapshot.UnlockedWorlds)
	local islands = countEntries(snapshot.UnlockedIslands)
	local inventory = snapshot.Inventory or {}
	local pets = countEntries(inventory.Pets)
	local levels = snapshot.Upgrades and snapshot.Upgrades.MasteryLevels
	if worlds == nil or islands == nil or pets == nil or type(levels) ~= "table" then
		return "UNDETERMINED", "Unlock, pet, or Mastery data is missing or disabled."
	end
	local masteryTotal = 0
	for _, level in pairs(levels) do if type(level) == "number" then masteryTotal += level end end
	local stage
	if worlds <= 1 and islands == 0 and pets == 0 and masteryTotal == 0 then stage = "BRAND_NEW"
	elseif worlds <= 1 and islands < 2 then stage = "EARLY_GAME"
	elseif worlds <= 1 then stage = "DEVELOPING"
	elseif worlds == 2 then stage = "MID_GAME"
	else stage = "ADVANCED" end
	return stage, string.format("%d unlocked worlds, %d discovered areas, %d pet records, %d Mastery levels. Full endgame completion is not inferred.",
		worlds, islands, pets, masteryTotal)
end

function OCBrain:Plan(snapshot, token)
	if token and token:CheckCancelled() then return nil end
	local stage, evidence = self:Classify(snapshot)
	local candidates = {}
	local config = self.Config
	local function add(id, title, reason, priority, family, prerequisites, metadata)
		table.insert(candidates, { Id = id, Title = title, Reason = reason, Priority = priority,
			Family = family, Prerequisites = prerequisites or {}, Metadata = metadata or {},
			RecommendationOnly = true, SnapshotRevision = snapshot.Revision })
	end
	if not config.GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS then
		add("RECOMMENDATIONS_DISABLED", "Recommendations are disabled", "Enable GENERAL_SETTINGS.ENABLE_RECOMMENDATIONS to select goals.", 1000, "RESOLVE_BLOCKERS")
	elseif not snapshot.Ready then
		add("WAIT_FOR_ACCOUNT", "Load the game's real player profile", "Account analysis needs LocalData:IsReady() and LocalData:Get().",
			1000, "RESOLVE_BLOCKERS", { "Game server supplies PlayerDataLoaded", "LocalData finishes loading" })
	else
		local inventory = snapshot.Inventory or {}
		local bubble = snapshot.Bubble or {}
		local progression = snapshot.AvailableProgression or {}
		local balances = snapshot.Balances or {}
		local function spendable(currency)
			if balances[currency] == nil then return nil end
			return math.max(0, balances[currency] - reserveFor(config, currency))
		end
		if config.BRAIN_SETTINGS.ENABLE_INVENTORY_RECOMMENDATIONS then
			if inventory.StorageUsed and inventory.StorageCapacity and inventory.StorageUsed >= inventory.StorageCapacity then
				add("REVIEW_INVENTORY", "Resolve full pet inventory", "Storage is full according to the game's own storage helpers; preserve pets and review storage upgrades.",
					950, "RESOLVE_BLOCKERS", { "Free storage through an approved non-destructive action" })
			end
			if inventory.UnresolvedEquippedIds and #inventory.UnresolvedEquippedIds > 0 then
				add("WAIT_FOR_PET_SYNC", "Wait for a consistent pet inventory", "Some equipped IDs are absent from the received pet records; avoid planning a team change from this snapshot.",
					960, "RESOLVE_BLOCKERS", { "LocalData resolves the equipped pet IDs" })
			end
		end
		if config.BRAIN_SETTINGS.ENABLE_EARNING_RECOMMENDATIONS and inventory.Pets and inventory.EquippedIds then
			local total = countEntries(inventory.Pets)
			if total > 0 and #inventory.EquippedIds == 0 then
				add("EQUIP_EXISTING_PETS", "Equip pets you already own", "The active team is empty even though the inventory contains pets.",
					850, "EARNING_POWER", { "Select owned pets for the active team" })
			elseif inventory.MaxEquipped and #inventory.EquippedIds < math.min(inventory.MaxEquipped, total) then
				add("FILL_EQUIP_SLOTS", "Use available pet equip slots", "Owned pet records and free equip slots are available; team changes are recommendations only.",
					720, "EARNING_POWER", { "Choose suitable owned pets" })
			end
		end
		if config.BUBBLE_SETTINGS.ENABLE_BUBBLE_RECOMMENDATIONS and bubble.Amount and bubble.Capacity and bubble.Capacity > 0 then
			if bubble.Amount / bubble.Capacity >= config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO then
				add("SELL_BUBBLES", "Sell the current bubble", "The bubble is at the configured fraction of effective capacity.",
					800, "RESOLVE_BLOCKERS", { "Use an accessible selling station" })
			end
		end
		if config.BRAIN_SETTINGS.ENABLE_EARNING_RECOMMENDATIONS and config.BUBBLE_SETTINGS.ENABLE_BUBBLE_RECOMMENDATIONS then
			local smallCapacity = bubble.Capacity and bubble.PowerPerBlow and bubble.PowerPerBlow > 0
				and bubble.Capacity / bubble.PowerPerBlow < config.BRAIN_SETTINGS.MINIMUM_BLOWS_PER_FILL
			for _, upgrade in ipairs(progression.Upgrades or {}) do
				if token and token:CheckCancelled() then return nil end
				local current = upgrade.Kind == "Gum" and bubble.BaseCapacity or bubble.BaseOutput
				if upgrade.Accessible and upgrade.OwnershipKnown and current and current > 0 and upgrade.BaseStat then
					local gain = upgrade.BaseStat / current - 1
					if gain >= config.BRAIN_SETTINGS.MINIMUM_UPGRADE_GAIN_RATIO then
						if upgrade.Owned then
							add("EQUIP_UPGRADE:" .. upgrade.Name, "Equip " .. upgrade.Name,
								"This owned upgrade has a higher base stat than the equipped upgrade; effective stats will refresh after a real change.",
								750, "EARNING_POWER", {}, { Upgrade = upgrade.Name, Kind = upgrade.Kind })
						else
							local cost = upgrade.Cost
							local funds = spendable(cost.Currency)
							if funds and type(cost.Amount) == "number" and cost.Amount >= 0 then
								local withinBudget = cost.Amount <= funds * config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION
								local efficiency = math.min(30, gain / math.max(1, cost.Amount) * 100)
								local priority = (withinBudget and 620 or 350) + efficiency
								if upgrade.Kind == "Gum" and smallCapacity then priority += 90 end
								add("BUY_UPGRADE:" .. upgrade.Name,
									(withinBudget and "Consider " or "Save for ") .. upgrade.Name,
									string.format("Base %s improvement %.0f%%; cost %.0f %s. Farming policy separately checks observed income and projected payback before purchasing.",
										upgrade.Kind == "Gum" and "capacity" or "flavor output", gain * 100, cost.Amount, cost.Currency),
									priority, "EARNING_POWER", withinBudget and {} or { "Meet the configured upgrade affordability budget" },
									{ Cost = cost, Upgrade = upgrade.Name, Kind = upgrade.Kind })
								end
						end
					end
				end
			end
		end
		if config.BRAIN_SETTINGS.ENABLE_WORLD_RECOMMENDATIONS and snapshot.UnlockedWorlds and snapshot.UnlockedIslands then
			for _, world in ipairs(progression.Worlds or {}) do
				if not world.Unlocked and world.Selected and world.Gate then
					local gate = world.Gate
					if not gate.OriginWorld or snapshot.UnlockedWorlds[gate.OriginWorld] == nil then continue end
					if gate.RequiredIsland and snapshot.UnlockedIslands[gate.RequiredIsland] == nil then
						add("DISCOVER:" .. gate.RequiredIsland, "Discover " .. gate.RequiredIsland,
							"The live gate to " .. world.Name .. " is located on this undiscovered island.",
							500, "WORLD_UNLOCKS", { "Reach the island through available game travel" }, { World = world.Name })
					elseif type(world.Cost) == "table" and world.Cost.Type == "Currency" then
						local funds = spendable(world.Cost.Currency)
						if funds and type(world.Cost.Amount) == "number" then
							local affordable = funds >= world.Cost.Amount
							add("UNLOCK_WORLD:" .. world.Name, (affordable and "Unlock " or "Save for ") .. world.Name,
								string.format("Current definition requires %.0f %s; the gate's island prerequisite is discovered.", world.Cost.Amount, world.Cost.Currency),
								affordable and 780 or 450, "WORLD_UNLOCKS",
								affordable and { "Use the verified world gate" } or { "Earn the remaining currency while keeping configured reserves" },
								{ Cost = world.Cost, World = world.Name, Gate = gate.Path })
						end
					end
					break
				end
			end
			for _, island in ipairs(progression.Islands or {}) do
				local selectedWorlds = config.BRAIN_SETTINGS.SELECTED_WORLDS
				if (#selectedWorlds == 0 or table.find(selectedWorlds, island.World)) and snapshot.UnlockedWorlds[island.World] ~= nil and not island.Unlocked then
					add("EXPLORE:" .. island.Name, "Discover " .. island.Name,
						"This scene-present island is the next undiscovered area in its world's height order; route execution is a later phase.",
						400, "WORLD_UNLOCKS", { "Verify and use a reachable game route" }, { World = island.World, Height = island.Height })
					break
				end
			end
		end
		if config.BRAIN_SETTINGS.ENABLE_MASTERY_RECOMMENDATIONS then
			for index, branch in ipairs(progression.Mastery or {}) do
				local cost = branch.NextCost
				if branch.Current ~= nil and type(cost) == "table" and cost.Type == "Currency" then
					local funds = spendable(cost.Currency)
					if funds and type(cost.Amount) == "number" then
						add("MASTERY:" .. branch.Name, "Review " .. branch.Name .. " Mastery level " .. tostring(branch.Current + 1),
							string.format("Next verified tier costs %.0f %s. Mastery purchasing remains a later-phase task.", cost.Amount, cost.Currency),
							(funds >= cost.Amount and 550 or 300) - index, "MASTERY",
							{ "Verify access to the Mastery facility", "Confirm the tier's benefit fits the selected goal" }, { Cost = cost })
					end
				end
			end
		end
		if #candidates == 0 then
			add("REVIEW_AVAILABLE_PROGRESSION", "Review available progression", "No supported recommendation can be established from the enabled readers and current definitions.",
				0, "RESOLVE_BLOCKERS", { "Review missing fields or approve another implementation phase" })
		end
	end
	local priorities = {}
	for index, family in ipairs(config.GENERAL_SETTINGS.PRIORITIES) do priorities[family] = index end
	table.sort(candidates, function(a, b)
		if a.Priority ~= b.Priority then return a.Priority > b.Priority end
		local left, right = priorities[a.Family] or 999, priorities[b.Family] or 999
		if left ~= right then return left < right end
		return a.Id < b.Id
	end)
	local selected = candidates[1]
	if self.Previous and os.clock() - self.SelectedAt < config.GENERAL_SETTINGS.MINIMUM_OBJECTIVE_HOLD_SECONDS then
		for _, candidate in ipairs(candidates) do
			if candidate.Id == self.Previous.Id and selected.Priority < candidate.Priority + config.GENERAL_SETTINGS.OBJECTIVE_SWITCH_PRIORITY_MARGIN then
				selected = candidate break
			end
		end
	end
	if not self.Previous or selected.Id ~= self.Previous.Id then self.SelectedAt = os.clock() end
	self.Previous = selected
	local nextObjective
	for _, candidate in ipairs(candidates) do
		if candidate.Id ~= selected.Id then nextObjective = candidate break end
	end
	return { Progression = stage, ProgressionEvidence = evidence, Objective = selected,
		NextObjective = nextObjective,
		Candidates = candidates, SnapshotRevision = snapshot.Revision,
		Reservations = selected.Metadata.Cost and { selected.Metadata.Cost } or {},
		ReservationPolicy = "Farming policy and native upgrade adapter enforce spending reserves before currency purchases." }
end

return OCBrain

end

-- src/OCFoundation/OCConfig.luau
factories["OCConfig"] = function()
--!strict
-- Central defaults. Currency purchases require explicit enablement.
return {
	GENERAL_SETTINGS = {
		OC_ENABLED = true, --// Permit the OC controls to start account analysis.
		AUTO_START = true, --// Start analysis automatically after the panel loads.
		PROGRESSION_PROFILE = "FULL_AUTO_PROGRESSION", --// Select the supported full-progression recommendation profile.
		ENABLE_RECOMMENDATIONS = true, --// Allow the brain to select the next objective.
		REPLAN_COOLDOWN_SECONDS = 1, --// Coalesce account changes before scheduling another analysis.
		MINIMUM_OBJECTIVE_HOLD_SECONDS = 10, --// Keep a valid recommendation briefly to avoid constant switching.
		OBJECTIVE_SWITCH_PRIORITY_MARGIN = 50, --// Require this priority improvement to replace a valid recommendation early.
		PRIORITIES = { "RESOLVE_BLOCKERS", "EARNING_POWER", "WORLD_UNLOCKS", "MASTERY" }, --// Break ties between eligible goal families in this order.
	},
	ACCOUNT_SETTINGS = {
		ENABLE_ACCOUNT_READER = true, --// Read the existing LocalData service and account updates.
		MODULE_LOAD_TIMEOUT_SECONDS = 10, --// Report game dependencies that have not finished requiring.
		ACCOUNT_LOAD_TIMEOUT_SECONDS = 20, --// Report missing real player data after this wait; never fabricate a profile.
		SNAPSHOT_REFRESH_SECONDS = 5, --// Refresh slowly as a fallback to account change notifications.
		MINIMUM_SNAPSHOT_INTERVAL_SECONDS = 0.5, --// Coalesce rapid data changes before copying the account inventory again.
		SELECTED_CURRENCIES = { "Coins", "Gems", "Tickets", "Pearls", "Leaves26", "RebirthShards26" }, --// Read these verified top-level balances when present.
		READ_PET_INVENTORY = true, --// Include pet records and resolve equipped IDs against the inventory.
		READ_ITEM_INVENTORY = true, --// Include received powerup and potion inventories independently of pets.
		READ_UPGRADES = true, --// Include owned gum and flavor upgrades.
		READ_MASTERY = true, --// Include received Mastery levels and Mastery upgrade records.
		READ_UNLOCKS = true, --// Include discovered areas and unlocked worlds.
	},
	BRAIN_SETTINGS = {
		ENABLE_EARNING_RECOMMENDATIONS = true, --// Recommend equipping existing pets and useful gum or flavor upgrades.
		ENABLE_WORLD_RECOMMENDATIONS = true, --// Recommend verified island discovery and world gate prerequisites.
		ENABLE_MASTERY_RECOMMENDATIONS = true, --// Recommend the next permanent Mastery tier from current definitions.
		ENABLE_INVENTORY_RECOMMENDATIONS = true, --// Highlight full inventory and unresolved equipped pet records.
		SELECTED_UPGRADES = {}, --// Restrict gum/flavor recommendations to these names; empty means all verified nonpremium entries.
		SELECTED_WORLDS = {}, --// Restrict world recommendations to these names; empty means scene-present permanent worlds.
		MASTERY_PRIORITIES = { "Pets", "Buffs", "Shops", "Minigames", "Rifts" }, --// Rank permanent Mastery branches; availability still comes from game definitions.
		MINIMUM_UPGRADE_GAIN_RATIO = 0.15, --// Ignore upgrades whose base stat improvement is smaller than this fraction.
		MINIMUM_BLOWS_PER_FILL = 10, --// Treat a small capacity relative to actual bubble power as a capacity bottleneck.
	},
	RESOURCE_SETTINGS = {
		COIN_RESERVE = 0, --// Exclude these coins from affordability recommendations.
		GEM_RESERVE = 0, --// Exclude these gems from affordability recommendations.
		TICKET_RESERVE = 0, --// Exclude these tickets from affordability recommendations.
		PEARL_RESERVE = 0, --// Exclude these pearls from affordability recommendations.
		MAXIMUM_UPGRADE_BALANCE_FRACTION = 0.25, --// Mark purchases above this fraction of spendable funds as savings objectives.
	},
	TASK_SETTINGS = {
		ENABLE_TASK_SCHEDULER = true, --// Grant one foreground lease to analysis, navigation, farming, selling, or spending.
		MAXIMUM_PENDING_TASKS = 8, --// Bound the scheduler queue; duplicate IDs replace pending work.
		TASK_TIMEOUT_SECONDS = 10, --// Cancel a stuck analysis and retain its foreground lease until it exits.
	},
	BUBBLE_SETTINGS = {
		ENABLE_BUBBLE_RECOMMENDATIONS = true, --// Recommend selling a full bubble or improving capacity/output.
		SELL_AT_CAPACITY_RATIO = 0.95, --// Recommend selling when this fraction of effective capacity is occupied.
		AUTO_BLOW_BUBBLES = true, --// Permit Brain-selected blowing through the verified BlowBubble command.
		AUTO_SELL_BUBBLES = true, --// Walk to a reachable same-island sell activation and wait for a real sale.
		AUTO_BUY_GUM = false, --// Explicitly authorize nonpremium bubble-capacity gum purchases.
		AUTO_BUY_FLAVORS = false, --// Explicitly authorize nonpremium bubble-power flavor purchases.
		ENABLE_SIMULTANEOUS_BLOWING = true, --// Allow the Brain to test blowing during a pickup cluster task.
		BLOW_COOLDOWN_SECONDS = 0.5, --// Minimum spacing between verified blow commands; UI and Bubble Lock guards still apply.
		SELL_CONFIRMATION_TIMEOUT_SECONDS = 8, --// Stop waiting if native selling does not reduce the actual bubble amount.
		SELL_RETRY_COOLDOWN_SECONDS = 20, --// Back off after an unavailable or unconfirmed sell attempt.
	},
	FARMING_SETTINGS = {
		AUTO_RESOURCE_FARM = true, --// Permit the Brain to schedule Phase 2 actions; false retains account analysis only.
		ENABLE_EFFICIENCY_COMPARISON = true, --// Compare measured currency gains for pickup, bubble, and combined sessions.
		ENABLE_ACTIVITY_SWITCHING = true, --// Reevaluate modes as yields or availability change; safety and full-bubble selling remain active.
		OBSERVATION_INTERVAL_SECONDS = 1, --// Sample live balances and scene availability without running an independent action loop.
		ACTION_SLICE_SECONDS = 6, --// Bound each foreground farming task before the Brain decides again.
		MINIMUM_RATE_SAMPLE_SECONDS = 15, --// Show a measured per-minute rate only after this much activity time.
		RATE_WINDOW_SECONDS = 180, --// Expire old activity measurements and area-specific efficiency evidence.
		EXPLORATION_INTERVAL_SECONDS = 60, --// Retest an eligible alternative after this interval to detect changed efficiency.
		MINIMUM_ACTIVITY_HOLD_SECONDS = 20, --// Hold an available mode briefly to avoid switching on tiny samples.
		ACTIVITY_SWITCH_GAIN_RATIO = 0.2, --// Require this fractional measured-rate advantage before switching a viable mode.
		EARNINGS_CONFIRMATION_TIMEOUT_SECONDS = 3, --// Allow delayed account credit to arrive before reporting a collection or sale as unconfirmed.
		BUBBLE_PROBE_TIMEOUT_SECONDS = 180, --// Bound an initial unsold bubble trial; an unfinished trial is not a measured sale rate.
		CURRENCY_PRIORITIES = { "Coins", "Gems", "Tickets", "Pearls" }, --// Fallback earning priorities when the recommended goal has no unmet currency cost.
		AUTO_FARM_FALLBACK = true, --// Permit another useful eligible activity when the preferred farming method is unavailable.
	},
	ISLAND_SETTINGS = {
		AUTO_SELECT_BEST_ISLAND = true, --// Rank already unlocked islands using goal-currency value and observed area rates.
		AUTO_TRAVEL_BEST_ISLAND = true, --// Use the native Teleport command only to verified unlocked island spawn paths.
		SELECTED_ISLANDS = {}, --// Empty considers all unlocked scene-present islands; names further restrict travel candidates.
		MIN_ISLAND_GAIN_ADVANTAGE_PERCENT = 25, --// Require this net earning advantage before leaving a useful current island.
		MIN_ISLAND_DWELL_SECONDS = 60, --// Stay on a viable island for this long before another farming-island switch.
		TRAVEL_COOLDOWN_SECONDS = 10, --// Minimum spacing between supported island or sell-station travel requests.
		TRAVEL_CONFIRMATION_TIMEOUT_SECONDS = 8, --// Stop travel when character proximity does not confirm the intended arrival.
		TRAVEL_RETRY_COOLDOWN_SECONDS = 30, --// Back off a destination after failed or unconfirmed travel.
		ARRIVAL_DISTANCE_STUDS = 20, --// Require the live character to arrive this close to the supported destination.
		UNMEASURED_TRAVEL_OVERHEAD_SECONDS = 5, --// Explicit planning estimate used until actual destination travel time is measured.
		UNMEASURED_COLLECTION_CYCLE_SECONDS = 30, --// Explicit estimate for unknown routing/respawn time; never displayed as measured earnings.
		EMPTY_ISLAND_CONFIRMATION_SECONDS = 15, --// Observe an empty arrived island this long before treating its pickups as unavailable.
		EMPTY_ISLAND_RETRY_SECONDS = 60, --// Back off empty islands; a newly observed eligible spawn clears this backoff early.
	},
	PICKUP_SETTINGS = {
		BULK_COLLECT_PICKUPS = true, --// Use the supported radius-cluster fallback; this game exposes no genuine island-wide batch API.
		ENABLE_CLUSTER_ROUTING = true, --// Walk between dense reachable clusters when the game has no island-wide batch API.
		FARM_CURRENCY_TYPES = {}, --// Empty includes every live currency pickup; names restrict OC route scoring and tracking.
		COLLECTION_REFRESH_SECONDS = 1, --// Minimum spacing between scene scans and subsequent collection cycles.
		ZONE_REFRESH_SECONDS = 10, --// Refresh live tagged zone definitions, including zones added or removed at runtime.
		MAXIMUM_ROUTE_DISTANCE_STUDS = 180, --// Reject cluster or sell destinations farther away than this walking distance estimate.
		MAXIMUM_VERTICAL_DIFFERENCE_STUDS = 20, --// Keep discovery and navigation on the player's current island height band.
		MAXIMUM_CLUSTER_CANDIDATES = 32, --// Bound density scoring while still scanning every rendered pickup.
		COLLECTION_SETTLE_SECONDS = 0.5, --// Wait in native range for the game collector after arriving at a cluster.
		UNREACHABLE_RETRY_SECONDS = 30, --// Back off failed cluster identities rather than repeatedly navigating to them.
		COLLECTION_RETRY_SECONDS = 5, --// Avoid immediately revisiting a cluster that produced no observed pickup disappearance.
		PATH_TIMEOUT_SECONDS = 3, --// Bound path computation and individual waypoint progress waits.
		MAXIMUM_PATH_DETOUR_RATIO = 2.5, --// Reject paths whose length greatly exceeds the direct route.
	},
	UPGRADE_SETTINGS = {
		ENABLE_SMART_UPGRADES = true, --// Let the Brain evaluate supported gum and flavor improvements before buying.
		AUTO_EQUIP_OWNED_UPGRADES = false, --// Explicitly allow switching to better owned gum or flavor through native commands.
		ENABLE_CAPACITY_UPGRADES = true, --// Allow gum purchases to address bubble storage bottlenecks; no pet-storage purchase API was found.
		ENABLE_FLAVOR_UPGRADES = true, --// Allow flavor purchases when bubble production is the selected earning bottleneck.
		SELECTED_UPGRADES = {}, --// Further restrict actual purchases/equips by upgrade name; empty allows verified recommendations.
		MAXIMUM_PURCHASE_COST = 1000000, --// Absolute per-purchase currency spending cap; premium costs are always excluded.
		MAXIMUM_PAYBACK_SECONDS = 300, --// Require a conservative measured bubble-income payback within this time for purchases.
		PURCHASE_CONFIRMATION_TIMEOUT_SECONDS = 8, --// Wait for real ownership/equipment changes after issuing one native shop command.
		PURCHASE_RETRY_COOLDOWN_SECONDS = 30, --// Back off unconfirmed purchases or equips instead of resending every decision cycle.
		ENABLE_GOAL_RESERVATION = true, --// Preserve the remaining selected world/Mastery goal funds before buying secondary upgrades.
	},
	FALL_EVENT_SETTINGS = {
		ENABLE_FALL_EVENT = false, --// Reserved; event shops, rebirths, and consumable tasks are not implemented.
		AUTO_REBIRTH = false, --// Reserved; leaf-resetting rebirths require later explicit enablement.
		AUTO_BUY_REBIRTH_UPGRADES = false, --// Reserved; no Autumn upgrade purchase executor is installed.
		AUTO_USE_FALL_ELIXIRS = false, --// Reserved; the current build never consumes elixirs.
		AUTO_BUY_AUTUMN_SHOP_ITEMS = false, --// Reserved; the current build never purchases event shop items.
		SELECTED_EGGS = {}, --// Reserve selected Autumn egg names for a later verified feature module.
		SELECTED_SHOP_ITEMS = {}, --// Reserve selected Autumn shop item names; an empty list authorizes no purchases.
		LEAF_RESERVE = 0, --// Preserve Leaves26 if a supported catalog ever uses it; event purchases remain disabled.
		REBIRTH_SHARD_RESERVE = 0, --// Preserve RebirthShards26 if a supported catalog uses it; no rebirth executor exists.
	},
	PET_SETTINGS = {
		SELECTED_PETS = {}, --// Reserve target pet names for later modules; no acquisition tasks run now.
		AUTO_HATCH = false, --// Reserved; hatching is outside the current build.
		AUTO_EQUIP = false, --// Reserved; pet team changes remain recommendations only.
		AUTO_DELETE_PETS = false, --// Reserved; destructive inventory operations are disabled.
		AUTO_CRAFT_SHINY = false, --// Reserved; the current build never consumes duplicate pets.
		AUTO_FUSE_PETS = false, --// Reserved; the current build never submits pets to machines.
	},
	STATUS_UI_SETTINGS = {
		ENABLE_STATUS_UI = true, --// Display the foundation panel and OC controls.
		SHOW_ACCOUNT_BALANCES = true, --// Show real balances and bubble capacity; missing values display unavailable.
		SHOW_PROGRESSION = true, --// Show the evidence-based progression category and unlock counts.
		SHOW_PREREQUISITES = true, --// Show why the next objective is blocked or ready.
		SHOW_DIAGNOSTICS = true, --// Show missing data and game dependency failures.
		SHOW_PETS = true, --// Display equipped pet IDs and inventory pet records.
		SHOW_INVENTORY = true, --// Display received potion and powerup inventory entries.
		SHOW_UPGRADES = true, --// Display owned gum, flavors, and received Mastery upgrades.
		SHOW_MASTERY = true, --// Display received levels and verified next tier costs.
		SHOW_WORLDS = true, --// Display actual unlocked world and island names.
		SHOW_FARMING = true, --// Show the chosen activity, useful currency, current island, and native collection constraint.
		SHOW_FARMING_RATES = true, --// Show per-currency observed earnings and sample time, including combined activity attribution.
		SHOW_ISLAND_CANDIDATES = true, --// Show measured versus estimated candidate earnings and travel evidence.
		MAXIMUM_DISPLAY_ENTRIES = 30, --// Bound each inventory display; GetStatus retains the complete read snapshot.
		PANEL_WIDTH_PIXELS = 390, --// Set the maximum panel width; small viewports scale down.
		PANEL_HEIGHT_PIXELS = 420, --// Set the maximum panel height; content can scroll.
	},
	DIAGNOSTIC_SETTINGS = {
		ENABLE_CONSOLE_LOGGING = true, --// Print prefixed control, account, dependency, and objective diagnostics.
		LOG_ACCOUNT_DETAILS = true, --// Print bounded pet, inventory, unlock, upgrade, and Mastery details on changes.
		LOG_DEPENDENCIES = true, --// Print game module load status changes and errors.
		MINIMUM_LOG_INTERVAL_SECONDS = 5, --// Rate limit account diagnostics while preserving the latest changed snapshot.
		MAXIMUM_LOG_ENTRIES = 30, --// Limit each detailed console inventory list; PrintAccount accepts an explicit limit.
	},
}

end

-- src/OCFoundation/OCController.luau
factories["OCController"] = function()
--!nonstrict
local AccountStateReader = requireOC("AccountStateReader")
local OCBrain = requireOC("OCBrain")
local TaskScheduler = requireOC("TaskScheduler")
local AccountPresentation = requireOC("AccountPresentation")
local FarmingCoordinator = requireOC("FarmingCoordinator")

local OCController = {}
OCController.__index = OCController

local function validate(config)
	for _, name in ipairs({ "GENERAL_SETTINGS", "ACCOUNT_SETTINGS", "BRAIN_SETTINGS", "RESOURCE_SETTINGS",
		"TASK_SETTINGS", "BUBBLE_SETTINGS", "FALL_EVENT_SETTINGS", "PET_SETTINGS", "STATUS_UI_SETTINGS", "DIAGNOSTIC_SETTINGS",
		"FARMING_SETTINGS", "ISLAND_SETTINGS", "PICKUP_SETTINGS", "UPGRADE_SETTINGS" }) do
		assert(type(config[name]) == "table", "Missing configuration category: " .. name)
	end
	for category, entries in pairs(config) do
		assert(type(category) == "string" and category:match("^[A-Z][A-Z_]*_SETTINGS$"), "Invalid configuration category")
		assert(type(entries) == "table", category .. " must be a table")
		for key, value in pairs(entries) do
			assert(type(key) == "string" and key:match("^[A-Z][A-Z_]*$"), "Invalid configuration setting")
			if key:match("^ENABLE_") or key:match("^AUTO_") or key:match("^READ_") or key:match("^SHOW_") or key == "OC_ENABLED" then
				assert(type(value) == "boolean", category .. "." .. key .. " must be true or false")
			elseif type(value) == "number" then
				assert(value == value and value >= 0 and value < math.huge, category .. "." .. key .. " must be finite and nonnegative")
			elseif type(value) == "table" then
				local count = 0
				for index, item in pairs(value) do
					assert(type(index) == "number" and index >= 1 and index % 1 == 0 and type(item) == "string", key .. " must be an array of strings")
					count += 1
				end
				assert(count == #value, key .. " must be a contiguous array")
			end
		end
	end
	for _, value in ipairs({ config.ACCOUNT_SETTINGS.MODULE_LOAD_TIMEOUT_SECONDS, config.ACCOUNT_SETTINGS.ACCOUNT_LOAD_TIMEOUT_SECONDS,
		config.ACCOUNT_SETTINGS.SNAPSHOT_REFRESH_SECONDS, config.TASK_SETTINGS.TASK_TIMEOUT_SECONDS, config.TASK_SETTINGS.MAXIMUM_PENDING_TASKS }) do
		assert(type(value) == "number" and value >= 1, "Timeouts, refresh intervals, and queue limits must be at least one")
	end
	assert(type(config.ACCOUNT_SETTINGS.MINIMUM_SNAPSHOT_INTERVAL_SECONDS) == "number" and config.ACCOUNT_SETTINGS.MINIMUM_SNAPSHOT_INTERVAL_SECONDS >= 0,
		"MINIMUM_SNAPSHOT_INTERVAL_SECONDS must be numeric and nonnegative")
	assert(config.GENERAL_SETTINGS.PROGRESSION_PROFILE == "FULL_AUTO_PROGRESSION", "Only FULL_AUTO_PROGRESSION is implemented")
	assert(config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO > 0 and config.BUBBLE_SETTINGS.SELL_AT_CAPACITY_RATIO <= 1, "Sell threshold must be in (0, 1]")
	assert(config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION > 0 and config.RESOURCE_SETTINGS.MAXIMUM_UPGRADE_BALANCE_FRACTION <= 1, "Upgrade budget fraction must be in (0, 1]")
	assert(config.STATUS_UI_SETTINGS.PANEL_WIDTH_PIXELS >= 280 and config.STATUS_UI_SETTINGS.PANEL_HEIGHT_PIXELS >= 280, "Panel dimensions must be at least 280 pixels")
	for _, limit in ipairs({ config.STATUS_UI_SETTINGS.MAXIMUM_DISPLAY_ENTRIES, config.DIAGNOSTIC_SETTINGS.MAXIMUM_LOG_ENTRIES,
		config.TASK_SETTINGS.MAXIMUM_PENDING_TASKS }) do
		assert(limit >= 1 and limit % 1 == 0, "Entry and queue limits must be positive integers")
	end
	for _, value in ipairs({ config.FARMING_SETTINGS.OBSERVATION_INTERVAL_SECONDS, config.FARMING_SETTINGS.ACTION_SLICE_SECONDS,
		config.FARMING_SETTINGS.MINIMUM_RATE_SAMPLE_SECONDS, config.FARMING_SETTINGS.RATE_WINDOW_SECONDS,
		config.PICKUP_SETTINGS.COLLECTION_REFRESH_SECONDS, config.PICKUP_SETTINGS.ZONE_REFRESH_SECONDS,
		config.PICKUP_SETTINGS.PATH_TIMEOUT_SECONDS, config.ISLAND_SETTINGS.TRAVEL_CONFIRMATION_TIMEOUT_SECONDS,
		config.UPGRADE_SETTINGS.PURCHASE_CONFIRMATION_TIMEOUT_SECONDS, config.BUBBLE_SETTINGS.SELL_CONFIRMATION_TIMEOUT_SECONDS }) do
		assert(value >= 1, "Farming observation, sample, slice, and timeout intervals must be at least one second")
	end
	assert(config.BUBBLE_SETTINGS.BLOW_COOLDOWN_SECONDS >= 0.5, "Native blowing cooldown must be at least 0.5 seconds")
	assert(config.FARMING_SETTINGS.RATE_WINDOW_SECONDS >= config.FARMING_SETTINGS.MINIMUM_RATE_SAMPLE_SECONDS, "Rate window is smaller than the minimum sample")
	assert(config.PICKUP_SETTINGS.MAXIMUM_CLUSTER_CANDIDATES >= 1 and config.PICKUP_SETTINGS.MAXIMUM_CLUSTER_CANDIDATES % 1 == 0, "Cluster candidate limit must be a positive integer")
	-- Unimplemented future executors still cannot be silently enabled.
	for _, category in ipairs({ "PET_SETTINGS", "FALL_EVENT_SETTINGS" }) do
		for key, value in pairs(config[category]) do
			if (key:match("^AUTO_") or key == "ENABLE_FALL_EVENT") and value then
				error("[OC] " .. category .. "." .. key .. " is reserved; its executor is not implemented in Phase 2")
			end
		end
	end
end

function OCController.new(config, player)
	validate(config)
	local self = setmetatable({}, OCController)
	self.Config = config
	self.Changed = Instance.new("BindableEvent")
	self.Reader = AccountStateReader.new(config, player)
	self.Brain = OCBrain.new(config)
	self.Scheduler = TaskScheduler.new(config.TASK_SETTINGS)
	self.State = "STOPPED"
	self.Generation = 0
	self.Plan = nil
	self.Error = nil
	self.Destroyed = false
	self.LastPlanAt = -math.huge
	self.Connections = {}
	self.Snapshot = self.Reader:GetSnapshot()
	self.Farming = FarmingCoordinator.new(self, player)
	table.insert(self.Connections, self.Reader.Changed.Event:Connect(function(snapshot)
		self.Snapshot = snapshot
		self:_diagnoseSnapshot(snapshot)
		self:_notify()
		self:_requestPlan(false)
	end))
	table.insert(self.Connections, self.Scheduler.Changed.Event:Connect(function() self:_notify() end))
	table.insert(self.Connections, self.Scheduler.Completed.Event:Connect(function(id, status, result, reason, definition)
		if self.Destroyed or self.State ~= "RUNNING" then return end
		if id == "OC_GAMEPLAY" then
			if definition and definition.Generation == self.Generation then
				self.Farming:Completed(status, result, reason)
				self.Reader:Refresh()
				self:_requestPlan(true)
			end
			return
		end
		if id ~= "ANALYZE_ACCOUNT" then return end
		if status == "COMPLETED" and type(result) == "table" and result.Generation == self.Generation then
			if result.SnapshotRevision < self.Snapshot.Revision then self:_requestPlan(true) return end
			self.Plan = result
			self.Error = nil
			self.LastPlanAt = os.clock()
			local goal = result.Objective
			if self.LastObjectiveId ~= goal.Id then
				self.LastObjectiveId = goal.Id
				self:Log("GOAL", goal.Id .. " | " .. goal.Title .. " | " .. goal.Reason)
				self:Log("PROGRESSION", result.Progression .. " | " .. result.ProgressionEvidence)
				if #goal.Prerequisites > 0 then self:Log("PREREQUISITES", table.concat(goal.Prerequisites, "; ")) end
			end
			local decision = self.Farming:Select(result)
			local taskDefinition = self.Farming:Definition(decision, self.Generation)
			if taskDefinition then
				local accepted, errorMessage = self.Scheduler:Submit(taskDefinition)
				if not accepted then self.Error = errorMessage self:Log("FARM][ERROR", errorMessage) end
			end
		elseif status == "FAILED" then self.Error = tostring(result) self:Log("DIAGNOSTIC", self.Error)
		elseif status == "CANCELLED" and reason == "Task timed out" then self.Error = reason self:Log("DIAGNOSTIC", reason) end
		self:_notify()
	end))
	-- Reading remains available while controls are stopped; no gameplay is executed.
	self.Reader:Start()
	self.Farming:StartObservations()
	return self
end

function OCController:Log(kind, message)
	if self.Config.DIAGNOSTIC_SETTINGS.ENABLE_CONSOLE_LOGGING then
		print("[OC][" .. kind .. "] " .. tostring(message))
	end
end

function OCController:PrintAccount(limit)
	if not self.Config.DIAGNOSTIC_SETTINGS.ENABLE_CONSOLE_LOGGING then return false, "Console logging is disabled" end
	limit = limit or self.Config.DIAGNOSTIC_SETTINGS.MAXIMUM_LOG_ENTRIES
	assert(type(limit) == "number" and limit >= 1 and limit % 1 == 0, "PrintAccount limit must be a positive integer")
	local snapshot = self.Reader:GetSnapshot()
	self:Log("ACCOUNT", "Status=" .. snapshot.Status .. "; Ready=" .. tostring(snapshot.Ready) .. "; Revision=" .. snapshot.Revision)
	if snapshot.Source then self:Log("SOURCE", snapshot.Source) end
	local sections = AccountPresentation.Sections(snapshot, self.Config, limit)
	for _, name in ipairs({ "Balances", "Pets", "Inventory", "Worlds", "Upgrades", "Mastery" }) do
		self:Log(string.upper(name), "\n" .. sections[name])
	end
	for _, diagnostic in ipairs(snapshot.Diagnostics or {}) do self:Log("DIAGNOSTIC", diagnostic) end
	if snapshot.UnavailableFields and #snapshot.UnavailableFields > 0 then
		self:Log("UNAVAILABLE", table.concat(snapshot.UnavailableFields, ", "))
	end
	return true
end

function OCController:_diagnoseSnapshot(snapshot)
	local settings = self.Config.DIAGNOSTIC_SETTINGS
	if not settings.ENABLE_CONSOLE_LOGGING then return end
	self.LastDependencies = self.LastDependencies or {}
	if settings.LOG_DEPENDENCIES then
		for name, entry in pairs(snapshot.Dependencies or {}) do
			local description = entry.Status .. (entry.Error and " | " .. entry.Error or "")
			if self.LastDependencies[name] ~= description then
				self.LastDependencies[name] = description
				self:Log("DEPENDENCY", name .. "=" .. description .. " | " .. entry.Path)
			end
		end
	end
	if self.LastAccountStatus ~= snapshot.Status then
		self.LastAccountStatus = snapshot.Status
		self:Log("ACCOUNT", "Status=" .. snapshot.Status .. "; Ready=" .. tostring(snapshot.Ready))
		for _, message in ipairs(snapshot.Diagnostics or {}) do self:Log("DIAGNOSTIC", message) end
	end
	if not snapshot.Ready then return end
	if self.AccountLogThread then return end
	local delaySeconds = math.max(0, settings.MINIMUM_LOG_INTERVAL_SECONDS - (os.clock() - (self.LastAccountLogAt or -math.huge)))
	self.AccountLogThread = task.delay(delaySeconds, function()
		self.AccountLogThread = nil
		if self.Destroyed then return end
		local latest = self.Reader:GetSnapshot()
		local sections = AccountPresentation.Sections(latest, self.Config, settings.MAXIMUM_LOG_ENTRIES)
		local summary = latest.Status .. "\n" .. sections.Balances
		if settings.LOG_ACCOUNT_DETAILS then
			for _, name in ipairs({ "Pets", "Inventory", "Worlds", "Upgrades", "Mastery" }) do summary ..= "\n" .. sections[name] end
		end
		if self.LastLoggedAccount ~= summary then
			self.LastLoggedAccount = summary
			self.LastAccountLogAt = os.clock()
			if settings.LOG_ACCOUNT_DETAILS then self:PrintAccount()
			else self:Log("BALANCES", sections.Balances) end
		end
	end)
end

function OCController:GetStatus()
	return { State = self.State, Snapshot = self.Reader:GetSnapshot(), Plan = self.Plan,
		Scheduler = self.Scheduler:GetStatus(), Farming = self.Farming:GetStatus(), Error = self.Error, Phase = 2 }
end

function OCController:_notify()
	if not self.Destroyed then self.Changed:Fire(self:GetStatus()) end
end

function OCController:_cancelReplan()
	if self.ReplanThread then pcall(task.cancel, self.ReplanThread) self.ReplanThread = nil end
end

function OCController:_requestPlan(force)
	if self.Destroyed or self.State ~= "RUNNING" then return end
	if force then self:_cancelReplan() end
	if self.ReplanThread then return end
	local delaySeconds = force and 0 or math.max(0, self.Config.GENERAL_SETTINGS.REPLAN_COOLDOWN_SECONDS - (os.clock() - self.LastPlanAt))
	local generation = self.Generation
	self.ReplanThread = task.delay(delaySeconds, function()
		self.ReplanThread = nil
		if self.Destroyed or self.State ~= "RUNNING" or generation ~= self.Generation then return end
		local snapshot = self.Reader:GetSnapshot()
		local accepted, reason = self.Scheduler:Submit({
			Id = "ANALYZE_ACCOUNT", Priority = 100,
			CanRun = function() return self.State == "RUNNING" and generation == self.Generation end,
			Execute = function(token)
				local result = self.Brain:Plan(snapshot, token)
				if result then result.Generation = generation end
				return result
			end,
			IsComplete = function(result) return type(result) == "table" and result.Objective ~= nil end,
		})
		if not accepted then self.Error = reason self:_notify() end
	end)
end

function OCController:Start()
	if self.Destroyed then return false, "Controller was destroyed" end
	if not self.Config.GENERAL_SETTINGS.OC_ENABLED then return false, "OC is disabled in OCConfig" end
	if not self.Config.ACCOUNT_SETTINGS.ENABLE_ACCOUNT_READER then return false, "Account reading is disabled" end
	if not self.Config.TASK_SETTINGS.ENABLE_TASK_SCHEDULER then return false, "Task scheduler is disabled" end
	if self.State == "RUNNING" then return true end
	if self.State == "PAUSED" then return self:Resume() end
	self.Generation += 1
	self.State = "RUNNING"
	self.Error = nil
	self.Brain:Reset()
	self.LastObjectiveId = nil
	self.Reader:Refresh()
	self.Scheduler:Resume()
	self:_requestPlan(true)
	self:_notify()
	self:Log("CONTROL", "START | account analysis and Brain-selected Phase 2 tasks enabled by Config")
	return true
end

function OCController:Pause()
	if self.Destroyed or self.State ~= "RUNNING" then return false, "OC is not running" end
	self.Generation += 1
	self.State = "PAUSED"
	self:_cancelReplan()
	self.Scheduler:Pause()
	self.Farming:Halt()
	self:_notify()
	self:Log("CONTROL", "PAUSE | recommendations paused; read-only account updates remain visible")
	return true
end

function OCController:Resume()
	if self.Destroyed or self.State ~= "PAUSED" then return false, "OC is not paused" end
	self.Generation += 1
	self.State = "RUNNING"
	self.Reader:Refresh()
	self.Scheduler:Resume()
	self:_requestPlan(true)
	self:_notify()
	self:Log("CONTROL", "RESUME | selecting from a fresh account snapshot")
	return true
end

function OCController:Stop()
	if self.Destroyed then return false end
	self.Generation += 1
	self.State = "STOPPED"
	self:_cancelReplan()
	self.Scheduler:Stop()
	self.Farming:Halt()
	self.Plan = nil
	self.Error = nil
	self.Brain:Reset()
	self.LastObjectiveId = nil
	self:_notify()
	self:Log("CONTROL", "STOP | objective and pending analysis cleared; account reader remains available")
	return true
end

function OCController:Destroy()
	if self.Destroyed then return end
	self:Stop()
	self.Destroyed = true
	if self.AccountLogThread then pcall(task.cancel, self.AccountLogThread) end
	if self.Interface then self.Interface:Destroy() end
	for _, connection in ipairs(self.Connections) do connection:Disconnect() end
	self.Reader:Destroy()
	self.Farming:Destroy()
	self.Scheduler:Destroy()
	self.Changed:Destroy()
	self:Log("CONTROL", "DESTROY | panel, subscriptions, and reader cleaned up")
end

return OCController

end

-- src/OCFoundation/OCInterface.luau
factories["OCInterface"] = function()
--!nonstrict
local AccountPresentation = requireOC("AccountPresentation")
local OCInterface = {}
OCInterface.__index = OCInterface

local function make(className, properties, parent)
	local instance = Instance.new(className)
	for key, value in pairs(properties) do instance[key] = value end
	instance.Parent = parent
	return instance
end

local function count(map)
	if type(map) ~= "table" then return "unavailable" end
	local total = 0 for _ in pairs(map) do total += 1 end
	return tostring(total)
end

function OCInterface.new(controller, playerGui)
	local settings = controller.Config.STATUS_UI_SETTINGS
	local self = setmetatable({ Controller = controller, Connections = {}, Destroyed = false }, OCInterface)
	if not settings.ENABLE_STATUS_UI then return self end
	self.Gui = make("ScreenGui", { Name = "OCFoundationPanel", ResetOnSpawn = false,
		DisplayOrder = 100, ZIndexBehavior = Enum.ZIndexBehavior.Sibling }, playerGui)
	self.Panel = make("Frame", { Name = "Panel", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -16, 0, 16),
		Size = UDim2.fromOffset(settings.PANEL_WIDTH_PIXELS, settings.PANEL_HEIGHT_PIXELS),
		BackgroundColor3 = Color3.fromRGB(20, 24, 35), BorderSizePixel = 0 }, self.Gui)
	make("UICorner", { CornerRadius = UDim.new(0, 14) }, self.Panel)
	make("UIStroke", { Color = Color3.fromRGB(65, 77, 97), Thickness = 1 }, self.Panel)
	make("UIPadding", { PaddingTop = UDim.new(0, 16), PaddingBottom = UDim.new(0, 14),
		PaddingLeft = UDim.new(0, 16), PaddingRight = UDim.new(0, 16) }, self.Panel)
	make("TextLabel", { Name = "Title", Size = UDim2.new(1, 0, 0, 24), BackgroundTransparency = 1,
		Text = "BUBBLE OC  /  PHASE 2", TextSize = 18, Font = Enum.Font.GothamBold,
		TextColor3 = Color3.fromRGB(241, 246, 255), TextXAlignment = Enum.TextXAlignment.Left }, self.Panel)
	make("TextLabel", { Name = "Scope", Position = UDim2.fromOffset(0, 29), Size = UDim2.new(1, 0, 0, 20),
		BackgroundTransparency = 1, Text = "Intelligent farming, selling and upgrades", TextSize = 12,
		Font = Enum.Font.Gotham, TextColor3 = Color3.fromRGB(162, 178, 203), TextXAlignment = Enum.TextXAlignment.Left }, self.Panel)
	local controls = make("Frame", { Name = "Controls", Position = UDim2.fromOffset(0, 61), Size = UDim2.new(1, 0, 0, 36),
		BackgroundTransparency = 1 }, self.Panel)
	make("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 7), SortOrder = Enum.SortOrder.LayoutOrder }, controls)
	self.Buttons = {}
	for index, action in ipairs({ "Start", "Pause", "Resume", "Stop" }) do
		local button = make("TextButton", { Name = action, LayoutOrder = index, Size = UDim2.new(0.25, -5.25, 1, 0),
			BackgroundColor3 = Color3.fromRGB(50, 60, 79), BorderSizePixel = 0, Text = string.upper(action),
			TextSize = 12, Font = Enum.Font.GothamBold, TextColor3 = Color3.fromRGB(240, 246, 255) }, controls)
		make("UICorner", { CornerRadius = UDim.new(0, 8) }, button)
		self.Buttons[action] = button
		table.insert(self.Connections, button.Activated:Connect(function()
			local ok, reason = controller[action](controller)
			if not ok and reason then controller.Error = reason controller:_notify() end
		end))
	end
	local content = make("ScrollingFrame", { Name = "Status", Position = UDim2.fromOffset(0, 112),
		Size = UDim2.new(1, 0, 1, -112), BackgroundTransparency = 1, BorderSizePixel = 0,
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3 }, self.Panel)
	make("UIListLayout", { Padding = UDim.new(0, 12), SortOrder = Enum.SortOrder.LayoutOrder }, content)
	self.Labels = {}
	for index, name in ipairs({ "State", "Objective", "Reason", "Prerequisites", "Farming", "Rates", "Islands", "Balances", "Progression", "Pets", "Inventory", "Worlds", "Upgrades", "Mastery", "Diagnostics" }) do
		self.Labels[name] = make("TextLabel", { Name = name, LayoutOrder = index, Size = UDim2.new(1, -8, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Text = "", TextWrapped = true,
			TextSize = name == "Objective" and 17 or 13, Font = name == "Objective" and Enum.Font.GothamBold or Enum.Font.Gotham,
			TextColor3 = name == "Objective" and Color3.fromRGB(137, 220, 213) or Color3.fromRGB(216, 226, 242),
			TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top }, content)
	end
	local function resize()
		local camera = workspace.CurrentCamera
		if not camera then return end
		local viewport = camera.ViewportSize
		self.Panel.Size = UDim2.fromOffset(math.min(settings.PANEL_WIDTH_PIXELS, math.max(200, viewport.X - 32)),
			math.min(settings.PANEL_HEIGHT_PIXELS, math.max(240, viewport.Y - 64)))
	end
	local cameraConnection
	local function hookCamera()
		if cameraConnection then cameraConnection:Disconnect() end
		if workspace.CurrentCamera then cameraConnection = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(resize) end
		resize()
	end
	table.insert(self.Connections, workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(hookCamera))
	self.DisconnectCamera = function() if cameraConnection then cameraConnection:Disconnect() end end
	hookCamera()
	table.insert(self.Connections, controller.Changed.Event:Connect(function(status) self:Render(status) end))
	self:Render(controller:GetStatus())
	return self
end

function OCInterface:Render(status)
	if self.Destroyed or not self.Gui then return end
	local settings = self.Controller.Config.STATUS_UI_SETTINGS
	local snapshot = status.Snapshot or {}
	local plan = status.Plan
	local objective = plan and plan.Objective
	self.Labels.State.Text = status.State .. "  ·  " .. (snapshot.Status or "NOT_STARTED")
	self.Labels.Objective.Text = objective and objective.Title or (status.State == "STOPPED" and "Press START to analyze your account" or "Analyzing account")
	self.Labels.Reason.Text = objective and objective.Reason or "Waiting for real account data and configured controls."
	self.Labels.Prerequisites.Visible = settings.SHOW_PREREQUISITES and objective ~= nil and #objective.Prerequisites > 0
	self.Labels.Prerequisites.Text = objective and "Prerequisites: " .. table.concat(objective.Prerequisites, " · ") or ""
	local sections = AccountPresentation.Sections(snapshot, self.Controller.Config, settings.MAXIMUM_DISPLAY_ENTRIES)
	self.Labels.Balances.Visible = settings.SHOW_ACCOUNT_BALANCES
	self.Labels.Balances.Text = sections.Balances
	for _, name in ipairs({ "Pets", "Inventory", "Worlds", "Upgrades", "Mastery" }) do
		self.Labels[name].Visible = settings["SHOW_" .. string.upper(name)]
		self.Labels[name].Text = string.upper(name) .. "\n" .. sections[name]
	end
	self.Labels.Progression.Visible = settings.SHOW_PROGRESSION
	self.Labels.Progression.Text = "Progression: " .. (plan and plan.Progression or "UNDETERMINED")
		.. "\nWorlds: " .. count(snapshot.UnlockedWorlds) .. "   Areas: " .. count(snapshot.UnlockedIslands)
		.. (plan and "\n" .. plan.ProgressionEvidence or "")
	local farming = status.Farming or {}
	local decision = farming.Decision or {}
	self.Labels.Farming.Visible = settings.SHOW_FARMING
	self.Labels.Farming.Text = "FARMING: " .. tostring(farming.Activity or decision.Mode or decision.Kind or "Waiting")
		.. "\nArea: " .. tostring(farming.Area or "unavailable") .. " | target: " .. tostring(decision.Currency or "unavailable")
		.. "\n" .. tostring(decision.Reason or "Observing accessible game mechanics")
		.. string.format("\nPickups: %d eligible / %d visible; %d unidentified | radius: %s", farming.EligiblePickups or 0, farming.VisiblePickups or 0,
			farming.UnknownPickups or 0, tostring(farming.Radius or "unavailable"))
		.. "\n" .. tostring(farming.CollectionMethod or "") .. "\n" .. tostring(farming.LastConfirmation or "")
		.. "\nObserved new models: " .. tostring(farming.ObservedSpawns or 0) .. "; respawn observations: " .. tostring(farming.RespawnObservations or 0)
	local rates = {}
	for mode, entry in pairs(farming.Rates or {}) do
		local values = {}
		for currency, value in pairs(entry.PerMinute) do table.insert(values, string.format("%.2f %s/min", value, currency)) end
		table.sort(values)
		table.insert(rates, mode .. " (" .. string.format("%.1fs", entry.Seconds) .. "): " .. (entry.Ready and (#values > 0 and table.concat(values, ", ") or "0 observed income") or "sampling"))
	end
	table.sort(rates)
	self.Labels.Rates.Visible = settings.SHOW_FARMING_RATES
	self.Labels.Rates.Text = "OBSERVED RATES (external rewards may affect attribution)\n" .. (#rates > 0 and table.concat(rates, "\n") or "No earning samples yet")
	local islands = {}
	for index, candidate in ipairs(decision.IslandCandidates or {}) do
		if index > settings.MAXIMUM_DISPLAY_ENTRIES then break end
		table.insert(islands, string.format("%s: %.2f %s/min | %s", candidate.Name, candidate.PerMinute, candidate.Currency, candidate.Evidence))
	end
	self.Labels.Islands.Visible = settings.SHOW_ISLAND_CANDIDATES and #islands > 0
	self.Labels.Islands.Text = "ELIGIBLE ISLANDS\n" .. table.concat(islands, "\n")
	local diagnostics = {}
	if status.Error then table.insert(diagnostics, status.Error) end
	if farming.Error then table.insert(diagnostics, farming.Error) end
	if snapshot.UnavailableFields and #snapshot.UnavailableFields > 0 then
		table.insert(diagnostics, "Unavailable fields: " .. table.concat(snapshot.UnavailableFields, ", "))
	end
	for _, message in ipairs(snapshot.Diagnostics or {}) do table.insert(diagnostics, message) end
	self.Labels.Diagnostics.Visible = settings.SHOW_DIAGNOSTICS and #diagnostics > 0
	self.Labels.Diagnostics.Text = table.concat(diagnostics, "\n")
	local enabled = { Start = status.State == "STOPPED", Pause = status.State == "RUNNING",
		Resume = status.State == "PAUSED", Stop = status.State ~= "STOPPED" }
	for name, button in pairs(self.Buttons) do
		button.Interactable = enabled[name]
		button.AutoButtonColor = enabled[name]
		button.TextTransparency = enabled[name] and 0 or 0.55
		button.BackgroundColor3 = name == "Start" and enabled[name] and Color3.fromRGB(32, 121, 111) or Color3.fromRGB(50, 60, 79)
	end
end

function OCInterface:Destroy()
	if self.Destroyed then return end
	self.Destroyed = true
	for _, connection in ipairs(self.Connections) do connection:Disconnect() end
	if self.DisconnectCamera then self.DisconnectCamera() end
	if self.Gui then self.Gui:Destroy() end
end

return OCInterface

end

-- src/OCFoundation/PickupTracker.luau
factories["PickupTracker"] = function()
--!nonstrict
-- Scene observation only. Native ClientScript owns pickup collection and credit.
local PickupTracker = {}
PickupTracker.__index = PickupTracker
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local function allowed(list, value) return #list == 0 or table.find(list, value) ~= nil end
local function worldOf(instance)
	local worlds = workspace:FindFirstChild("Worlds")
	local node = instance
	while node and node ~= workspace do
		if node.Parent == worlds then return node.Name end
		node = node.Parent
	end
	return nil
end
local function fingerprint(model)
	local pieces = {}
	for _, part in ipairs(model:GetDescendants()) do
		if part:IsA("MeshPart") then
			table.insert(pieces, part.Name .. ":" .. part.MeshId .. ":" .. part.TextureID .. ":" .. tostring(part.Size))
		elseif part:IsA("SpecialMesh") then
			table.insert(pieces, part.Name .. ":" .. part.MeshId .. ":" .. part.TextureId .. ":" .. tostring(part.Scale))
		elseif part:IsA("BasePart") then
			table.insert(pieces, part.Name .. ":" .. part.ClassName .. ":" .. tostring(part.Size) .. ":" .. tostring(part.Color))
		end
	end
	table.sort(pieces)
	return #pieces > 0 and table.concat(pieces, "|") or nil
end
local function spawnFor(area, world)
	local worlds = workspace:FindFirstChild("Worlds")
	local root = worlds and worlds:FindFirstChild(world or "")
	if not root then return nil end
	if area == world then
		local travel = root:FindFirstChild("FastTravel")
		-- PortalSpawn is the verified return destination used by native island portals.
		return (travel and travel:FindFirstChild("Spawn")) or root:FindFirstChild("PortalSpawn")
	end
	local islands = root:FindFirstChild("Islands")
	local island = islands and islands:FindFirstChild(area)
	local model = island and island:FindFirstChild("Island")
	local portal = model and model:FindFirstChild("Portal")
	return portal and portal:FindFirstChild("Spawn")
end

function PickupTracker.new(config, reader, player)
	return setmetatable({ Config = config, Reader = reader, Player = player, Zones = {}, Areas = {},
		Metadata = {}, Models = {}, Backoff = {}, Connections = {}, Prefabs = nil,
		LastZoneRefresh = -math.huge, LastScan = -math.huge, ObservedSpawns = 0, Disappeared = 0,
		RespawnObservations = 0, Destroyed = false }, PickupTracker)
end

function PickupTracker:Root()
	local character = self.Player and self.Player.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if root and humanoid and humanoid.Health > 0 then return root, humanoid end
	return nil
end

function PickupTracker:_hookSpawn()
	if self.SpawnConnection or not self.Config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS then return end
	local remotes = ReplicatedStorage:FindFirstChild("Remotes")
	local pickups = remotes and remotes:FindFirstChild("Pickups")
	local spawn = pickups and pickups:FindFirstChild("SpawnPickups")
	if not spawn or not spawn:IsA("RemoteEvent") then return end
	self.SpawnConnection = spawn.OnClientEvent:Connect(function(payload)
		if type(payload) ~= "table" then return end
		for _, entry in pairs(payload) do
			if type(entry) == "table" and type(entry.Id) == "string" and type(entry.Visual) == "string" then
				self.Metadata[entry.Id] = { Root = entry.Root, Visual = entry.Visual, At = os.clock() }
			end
		end
	end)
	table.insert(self.Connections, self.SpawnConnection)
end

function PickupTracker:_zones(now)
	if now - self.LastZoneRefresh < self.Config.PICKUP_SETTINGS.ZONE_REFRESH_SECONDS then return end
	local getZones = self.Reader:_dependency("GetPickupZones")
	if type(getZones) ~= "function" then self.Error = "GetPickupZones interface is unavailable" return end
	self.LastZoneRefresh = now
	local ok, zones = pcall(getZones)
	if not ok or type(zones) ~= "table" then self.Error = "Zone read failed: " .. tostring(zones) return end
	self.Zones = zones
	self.Error = nil
end

function PickupTracker:_prefabs()
	if self.Prefabs then return end
	local assets = ReplicatedStorage:FindFirstChild("Assets")
	local pickups = assets and assets:FindFirstChild("Pickups")
	if not pickups then return end
	self.Prefabs = {}
	for _, prefab in ipairs(pickups:GetChildren()) do
		local key = fingerprint(prefab)
		if key then
			if self.Prefabs[key] ~= nil then self.Prefabs[key] = false else self.Prefabs[key] = prefab.Name end
		end
	end
end

function PickupTracker:Refresh(snapshot, now)
	if self.Destroyed or not self.Config.FARMING_SETTINGS.AUTO_RESOURCE_FARM then return end
	self:_hookSpawn()
	self:_zones(now)
	local root = self:Root()
	local position = root and root.Position
	local profile = self.Reader:GetLiveProfile()
	local stats = self.Reader:_dependency("StatsUtil")
	local oldAreas, areas, current, currentDistance = self.Areas, {}, nil, math.huge
	local multiplierCache = {}
	for zoneRoot, data in pairs(self.Zones) do
		if zoneRoot.Parent and zoneRoot:IsDescendantOf(workspace) and data.Zone and type(data.Area) == "string" and data.Area ~= "" then
			local world = worldOf(zoneRoot)
			local key = (world or "Live event") .. "/" .. data.Area
			local prior = oldAreas[key]
			local area = areas[key] or { Key = key, Name = data.Area, World = world, Zones = {}, Currencies = {},
				Expected = {}, Available = {}, VisibleCount = 0, EligibleCount = 0, UnknownCount = 0,
				LastDepletionAt = prior and prior.LastDepletionAt, RespawnSeconds = prior and prior.RespawnSeconds,
				LastSpawnAt = prior and prior.LastSpawnAt, TravelSeconds = prior and prior.TravelSeconds }
			areas[key] = area
			table.insert(area.Zones, { Root = zoneRoot, Data = data })
			local sumChance = 0
			for _, pickup in ipairs(data.Pickups or {}) do sumChance += type(pickup.Chance) == "number" and pickup.Chance or 0 end
			for _, pickup in ipairs(data.Pickups or {}) do
				local item = pickup.Item and pickup.Item.Item
				if item and item.Type == "Currency" and type(item.Currency) == "string" and type(item.Amount) == "number" then
					area.Currencies[item.Currency] = true
					self.Reader:RegisterCurrency(item.Currency)
					local multiplier = multiplierCache[item.Currency]
					if multiplier == nil and profile and stats and type(stats.GetCurrencyMultiplier) == "function" then
						local success, value = pcall(stats.GetCurrencyMultiplier, stats, profile, item.Currency)
						if success and type(value) == "number" and value > 0 then multiplier = value end
						multiplierCache[item.Currency] = multiplier or false
					end
					if multiplier == false then multiplier = nil end
					area.Multipliers = area.Multipliers or {}
					area.Multipliers[item.Currency] = multiplier
					local count = type(data.Count) == "number" and data.Count or nil
					if count and multiplier and sumChance > 0 and type(pickup.Chance) == "number" then
						area.Expected[item.Currency] = (area.Expected[item.Currency] or 0) + count * pickup.Chance / sumChance * item.Amount * multiplier
					end
				end
			end
			if position and math.abs(position.Y - data.Zone.Height) <= self.Config.PICKUP_SETTINGS.MAXIMUM_VERTICAL_DIFFERENCE_STUDS then
				local distance = data.Zone:GetDistanceToPoint(position)
				if distance < currentDistance and distance <= self.Config.PICKUP_SETTINGS.MAXIMUM_ROUTE_DISTANCE_STUDS then
					current, currentDistance = area, distance
				end
			end
		end
	end
	for _, area in pairs(areas) do
		area.Unlocked = area.World ~= nil and snapshot.UnlockedWorlds ~= nil and snapshot.UnlockedWorlds[area.World] ~= nil
			and (area.Name == area.World or (snapshot.UnlockedIslands and snapshot.UnlockedIslands[area.Name] ~= nil))
		-- A live special zone may be farmed where the player already is, but no unverified event teleport is invented.
		if area == current then area.Unlocked = true end
		area.Spawn = spawnFor(area.Name, area.World)
		if area.Spawn and not area.Spawn:IsA("BasePart") then area.Spawn = nil end
	end
	self.Areas, self.Current = areas, current
	if self.LastAreaKey ~= (current and current.Key) then self.LastAreaKey = current and current.Key self.ArrivedAt = now end
	if now - self.LastScan >= self.Config.PICKUP_SETTINGS.COLLECTION_REFRESH_SECONDS then
		self.LastScan = now
		self:_scan(now)
	else
		-- Preserve counts between expensive scans, but rebuild zone eligibility each observation.
		for key, area in pairs(areas) do
			local previous = oldAreas[key]
			if previous then
				area.Available, area.VisibleCount, area.EligibleCount, area.UnknownCount = previous.Available, previous.VisibleCount, previous.EligibleCount, previous.UnknownCount
			end
		end
	end
end

function PickupTracker:_scan(now)
	if not self.Config.PICKUP_SETTINGS.BULK_COLLECT_PICKUPS then return end
	self:_prefabs()
	local rendered = workspace:FindFirstChild("Rendered")
	local folder = rendered and rendered:FindFirstChild("Pickups")
	local seen = {}
	for _, model in ipairs(folder and folder:GetChildren() or {}) do
		if not model:IsA("Model") then continue end
		local position = model:GetPivot().Position
		local metadata = self.Metadata[model.Name]
		local zoneData = metadata and self.Zones[metadata.Root]
		local area
		if zoneData then area = self.Areas[(worldOf(metadata.Root) or "Live event") .. "/" .. zoneData.Area] end
		if not area then
			local matches = 0
			for _, candidate in pairs(self.Areas) do
				for _, zone in ipairs(candidate.Zones) do
					if math.abs(position.Y - zone.Data.Zone.Height) < self.Config.PICKUP_SETTINGS.MAXIMUM_VERTICAL_DIFFERENCE_STUDS
						and zone.Data.Zone:IsPointInside(position) then
						matches += 1 area = candidate zoneData = zone.Data break
					end
				end
			end
			if matches ~= 1 then area = nil end
		end
		if not area then continue end
		area.VisibleCount += 1
		local old = self.Models[model]
		local visual = metadata and metadata.Visual or (old and old.Visual)
		if not visual and self.Prefabs then visual = self.Prefabs[fingerprint(model)] end
		local item, conflicting
		for _, definition in ipairs(zoneData.Pickups or {}) do
			if definition.Item and definition.Item.Visual == visual then
				local candidate = definition.Item.Item
				if item and (candidate.Type ~= item.Type or candidate.Currency ~= item.Currency or candidate.Amount ~= item.Amount) then conflicting = true end
				item = candidate
			end
		end
		seen[model] = true
		local record = old or { Model = model, Id = model.Name, FirstSeenAt = now }
		record.Position, record.AreaKey, record.Visual = position, area.Key, visual
		record.Currency = not conflicting and item and item.Type == "Currency" and item.Currency or nil
		record.Amount = record.Currency and item.Amount or nil
		self.Models[model] = record
		if not old then
			self.ObservedSpawns += 1
			if area.LastDepletionAt then
				local interval = now - area.LastDepletionAt
				if interval > 0 then area.RespawnSeconds = interval self.RespawnObservations += 1 end
				area.LastDepletionAt = nil
			end
			area.LastSpawnAt = now
		end
		if record.Currency and allowed(self.Config.PICKUP_SETTINGS.FARM_CURRENCY_TYPES, record.Currency) then
			area.EligibleCount += 1
			area.Available[record.Currency] = (area.Available[record.Currency] or 0) + 1
		elseif not item then area.UnknownCount += 1 end
	end
	for model, record in pairs(self.Models) do
		if not seen[model] then
			self.Disappeared += 1
			local area = self.Areas[record.AreaKey]
			if area and not model.Parent then area.LastDepletionAt = now end
			self.Models[model] = nil
			if self.Sweep then self.Sweep.Pending[model] = nil end
		end
	end
	for id, metadata in pairs(self.Metadata) do if now - metadata.At > 300 then self.Metadata[id] = nil end end
	for id, failure in pairs(self.Backoff) do if now >= failure.Until then self.Backoff[id] = nil end end
end

function PickupTracker:BackOff(records, seconds, reason)
	for _, record in ipairs(records) do
		self.Backoff[record.Id] = { Until = os.clock() + seconds, Reason = reason }
		if self.Sweep then self.Sweep.Pending[record.Model] = nil end
	end
end

function PickupTracker:Cluster(currency)
	local root, humanoid = self:Root()
	if not root or not self.Current then return nil end
	local profile = self.Reader:GetLiveProfile()
	local stats = self.Reader:_dependency("StatsUtil")
	local ok, range = pcall(function() return stats:GetPickupRange(profile) end)
	if not ok or type(range) ~= "number" or range <= 0 then return nil end
	self.Range = range
	local records = {}
	for _, record in pairs(self.Models) do
		if record.AreaKey == self.Current.Key and record.Currency and allowed(self.Config.PICKUP_SETTINGS.FARM_CURRENCY_TYPES, record.Currency)
			and record.Model.Parent and not self.Backoff[record.Id] then table.insert(records, record) end
	end
	table.sort(records, function(a, b) return a.Id < b.Id end)
	-- Freeze the currently eligible island set for a sweep. New spawns enter the next sweep,
	-- so repeated new coin spawns cannot indefinitely starve remaining gems/event currencies.
	if not self.Sweep or self.Sweep.AreaKey ~= self.Current.Key or next(self.Sweep.Pending) == nil then
		self.SweepSequence = (self.SweepSequence or 0) + 1
		self.Sweep = { Id = self.SweepSequence, AreaKey = self.Current.Key, Pending = {}, Total = #records }
		for _, record in ipairs(records) do self.Sweep.Pending[record.Model] = true end
	end
	local pendingRecords = {}
	for _, record in ipairs(records) do if self.Sweep.Pending[record.Model] then table.insert(pendingRecords, record) end end
	records = pendingRecords
	local points = { root.Position }
	if self.Config.PICKUP_SETTINGS.ENABLE_CLUSTER_ROUTING then
		local stride = math.max(1, math.ceil(#records / self.Config.PICKUP_SETTINGS.MAXIMUM_CLUSTER_CANDIDATES))
		for index = 1, #records, stride do
			local position = records[index].Position
			table.insert(points, Vector3.new(position.X, root.Position.Y, position.Z))
		end
	end
	local best
	for _, point in ipairs(points) do
		local distance = (point - root.Position).Magnitude
		if distance > self.Config.PICKUP_SETTINGS.MAXIMUM_ROUTE_DISTANCE_STUDS then continue end
		local covered, useful, value = {}, 0, 0
		for _, record in ipairs(records) do
			if (record.Position - point).Magnitude <= math.max(0, range - 1) then
				table.insert(covered, record)
				if record.Currency == currency then useful += 1 value += record.Amount or 0 end
			end
		end
		-- Score only the target currency. All eligible currencies inside the chosen radius are collected by the game.
		local travel = 1 + distance / math.max(1, humanoid.WalkSpeed)
		local score, coverageScore = value / travel, #covered / travel
		if #covered > 0 and (not best or score > best.Score or (score == best.Score and coverageScore > best.CoverageScore)) then
			best = { Position = point, Records = covered, Score = score, Radius = range, Distance = distance,
				AreaKey = self.Current.Key, RelevantCount = useful, Currency = currency, CoverageScore = coverageScore,
				SweepId = self.Sweep.Id, SweepTotal = self.Sweep.Total, SweepRemaining = #records }
		end
	end
	return best
end

function PickupTracker:Destroy()
	self.Destroyed = true
	for _, connection in ipairs(self.Connections) do connection:Disconnect() end
	table.clear(self.Models) table.clear(self.Metadata) table.clear(self.Backoff)
end

return PickupTracker

end

-- src/OCFoundation/ResourceMetrics.luau
factories["ResourceMetrics"] = function()
--!nonstrict
-- Observed balance deltas, never pickup face values or predicted sale credit.
local ResourceMetrics = {}
ResourceMetrics.__index = ResourceMetrics

function ResourceMetrics.new(settings)
	return setmetatable({ Settings = settings, Samples = {}, Active = nil, Last = nil, Totals = {},
		ConfirmedCycles = 0, UnconfirmedCycles = 0, LastConfirmation = "No collection verified yet" }, ResourceMetrics)
end

function ResourceMetrics:Observe(balances, now)
	local previous = self.Last
	self.Last = { At = now, Balances = table.clone(balances) }
	if not previous or not self.Active then return {} end
	local dt = math.max(0, now - previous.At)
	local gains, spending = {}, false
	for currency, value in pairs(balances) do
		local old = previous.Balances[currency]
		if type(value) == "number" and type(old) == "number" then
			if value < old then spending = true end
			if value > old then gains[currency] = value - old end
		end
	end
	-- A purchase or externally observed spend makes this interval unsuitable for rate attribution.
	if spending then return {} end
	if dt > 0 then
		table.insert(self.Samples, { At = now, Seconds = dt, Mode = self.Active.Mode,
			Scope = self.Active.Scope, Gains = gains })
		for currency, value in pairs(gains) do self.Totals[currency] = (self.Totals[currency] or 0) + value end
	end
	self:Prune(now)
	return gains
end

function ResourceMetrics:Prune(now)
	while self.Samples[1] and now - self.Samples[1].At > self.Settings.RATE_WINDOW_SECONDS do
		table.remove(self.Samples, 1)
	end
end

function ResourceMetrics:SetMode(mode, scope, balances, now)
	self:Observe(balances, now)
	if not mode then self.Active = nil return end
	if not self.Active or self.Active.Mode ~= mode or self.Active.Scope ~= scope then
		self.Active = { Mode = mode, Scope = scope, StartedAt = now }
	end
end

function ResourceMetrics:Rates(scope, now)
	self:Prune(now)
	local result = {}
	for _, sample in ipairs(self.Samples) do
		if sample.Scope == scope then
			local entry = result[sample.Mode] or { Seconds = 0, Earned = {}, PerMinute = {}, LastAt = sample.At }
			result[sample.Mode] = entry
			entry.Seconds += sample.Seconds
			entry.LastAt = math.max(entry.LastAt, sample.At)
			for currency, amount in pairs(sample.Gains) do entry.Earned[currency] = (entry.Earned[currency] or 0) + amount end
		end
	end
	for _, entry in pairs(result) do
		entry.Ready = entry.Seconds >= self.Settings.MINIMUM_RATE_SAMPLE_SECONDS
		if entry.Ready then
			for currency, amount in pairs(entry.Earned) do entry.PerMinute[currency] = amount * 60 / entry.Seconds end
		end
	end
	return result
end

function ResourceMetrics:ConfirmCycle(before, after, source)
	local gains = {}
	for currency, value in pairs(after) do
		if type(before[currency]) == "number" and value > before[currency] then gains[currency] = value - before[currency] end
	end
	if next(gains) then
		self.ConfirmedCycles += 1
		local items = {}
		for currency, value in pairs(gains) do table.insert(items, string.format("+%.0f %s", value, currency)) end
		table.sort(items)
		self.LastConfirmation = source .. " | actual balance increased: " .. table.concat(items, ", ")
	else
		self.UnconfirmedCycles += 1
		self.LastConfirmation = source .. " | no positive balance change confirmed"
	end
	return gains
end

return ResourceMetrics

end

-- src/OCFoundation/TaskScheduler.luau
factories["TaskScheduler"] = function()
--!nonstrict
-- Cooperative cancellation retains the foreground lease until Execute returns.
local TaskScheduler = {}
TaskScheduler.__index = TaskScheduler

function TaskScheduler.new(settings)
	local self = setmetatable({}, TaskScheduler)
	self.Settings = settings
	self.Changed = Instance.new("BindableEvent")
	self.Completed = Instance.new("BindableEvent")
	self.Queue = {}
	self.Active = nil
	self.Enabled = false
	self.Destroyed = false
	self.Sequence = 0
	return self
end

function TaskScheduler:GetStatus()
	return {
		ActiveTask = self.Active and self.Active.Definition.Id or nil,
		CancellationPending = self.Active ~= nil and self.Active.Token.Cancelled,
		PendingCount = #self.Queue,
		Enabled = self.Enabled,
	}
end

function TaskScheduler:_pump()
	if self.Destroyed or not self.Enabled or self.Active or #self.Queue == 0 then return end
	table.sort(self.Queue, function(a, b)
		if a.Priority == b.Priority then return a.Sequence < b.Sequence end
		return a.Priority > b.Priority
	end)
	local definition = table.remove(self.Queue, 1)
	local token = { Cancelled = false, Reason = nil }
	function token:CheckCancelled()
		return self.Cancelled
	end
	local active = { Definition = definition, Token = token }
	self.Active = active
	self.Changed:Fire(self:GetStatus())
	active.TimeoutThread = task.delay(definition.TimeoutSeconds or self.Settings.TASK_TIMEOUT_SECONDS, function()
		if self.Active == active then self:CancelActive("Task timed out") end
	end)
	-- Defer so the timeout/thread handles are installed before a synchronous task finishes.
	active.Thread = task.defer(function()
		local skipped = false
		local ok, result = xpcall(function()
			if token.Cancelled then return nil end
			if definition.CanRun and not definition.CanRun() then skipped = true return nil end
			local output = definition.Execute(token)
			if token.Cancelled then return nil end
			if definition.IsComplete and not definition.IsComplete(output) then
				error("Task returned without satisfying its completion check")
			end
			return output
		end, debug.traceback)
		if active.TimeoutThread then pcall(task.cancel, active.TimeoutThread) end
		if self.Active == active then self.Active = nil end
		if self.Destroyed then return end
		local status = token.Cancelled and "CANCELLED" or (skipped and "SKIPPED" or (ok and "COMPLETED" or "FAILED"))
		self.Completed:Fire(definition.Id, status, result, token.Reason, definition)
		self.Changed:Fire(self:GetStatus())
		self:_pump()
	end)
end

function TaskScheduler:Submit(definition)
	if self.Destroyed or not self.Settings.ENABLE_TASK_SCHEDULER then return false, "Scheduler unavailable" end
	assert(type(definition.Id) == "string" and type(definition.Execute) == "function", "Invalid task")
	assert(type(definition.Priority) == "number", "Task priority must be numeric")
	for index, pending in ipairs(self.Queue) do
		if pending.Id == definition.Id then table.remove(self.Queue, index) break end
	end
	if #self.Queue >= self.Settings.MAXIMUM_PENDING_TASKS then return false, "Queue is full" end
	self.Sequence += 1
	definition.Sequence = self.Sequence
	table.insert(self.Queue, definition)
	self.Changed:Fire(self:GetStatus())
	self:_pump()
	return true
end

function TaskScheduler:CancelActive(reason)
	if not self.Active then return end
	self.Active.Token.Cancelled = true
	self.Active.Token.Reason = reason or "Cancelled"
	self.Changed:Fire(self:GetStatus())
end

function TaskScheduler:Pause()
	self.Enabled = false
	table.clear(self.Queue)
	self:CancelActive("Paused")
	self.Changed:Fire(self:GetStatus())
end

function TaskScheduler:Resume()
	if self.Destroyed or not self.Settings.ENABLE_TASK_SCHEDULER then return end
	self.Enabled = true
	self.Changed:Fire(self:GetStatus())
	self:_pump()
end

function TaskScheduler:Stop()
	self.Enabled = false
	table.clear(self.Queue)
	self:CancelActive("Stopped")
	self.Changed:Fire(self:GetStatus())
end

function TaskScheduler:Destroy()
	if self.Destroyed then return end
	self:Stop()
	self.Destroyed = true
	if self.Active then
		if self.Active.TimeoutThread then pcall(task.cancel, self.Active.TimeoutThread) end
		if self.Active.Thread then pcall(task.cancel, self.Active.Thread) end
		self.Active = nil
	end
	self.Changed:Destroy()
	self.Completed:Destroy()
end

return TaskScheduler

end

-- src/OC.luau
local function entry()
--!nonstrict
-- The compiled bundle returns this initializer. It creates no Script or ModuleScript instances.
local Defaults = requireOC("OCConfig")
local ConfigResolver = requireOC("ConfigResolver")
local OCController = requireOC("OCController")
local OCInterface = requireOC("OCInterface")

return function(customConfig)
	local config = ConfigResolver.Resolve(Defaults, customConfig)
	assert(config.GENERAL_SETTINGS.OC_ENABLED, "[OC] OC_ENABLED=false; initialization is disabled")
	assert(game:GetService("RunService"):IsClient(), "[OC] OC requires a client runtime; server loadstring cannot read client LocalData")
	local players = game:GetService("Players")
	local player = players.LocalPlayer
	assert(player, "[OC] Players.LocalPlayer is unavailable; run after joining your authorized client test environment")
	local playerGui
	if config.STATUS_UI_SETTINGS.ENABLE_STATUS_UI then
		playerGui = player:WaitForChild("PlayerGui", config.ACCOUNT_SETTINGS.MODULE_LOAD_TIMEOUT_SECONDS)
		assert(playerGui, "[OC] PlayerGui did not load before the configured timeout")
	end
	local controller = OCController.new(config, player)
	local ok, result = xpcall(function()
		controller.Interface = OCInterface.new(controller, playerGui)
		controller:Log("INIT", "Phase 2 candidate initialized | PlaceId=" .. tostring(game.PlaceId) .. " | build=655e1bce2d06 | user testing pending")
		controller:Log("SCOPE", "Brain-coordinated unlocked island farming, native radius clusters, bubbles, selling and configured currency upgrades.")
		controller:Log("FARM][BULK", "No genuine island-wide batch pickup interface found; native collection operates per ID within StatsUtil:GetPickupRange.")
		if config.GENERAL_SETTINGS.AUTO_START then
			local started, reason = controller:Start()
			if not started then controller.Error = reason controller:Log("CONTROL", reason) controller:_notify() end
		end
		return controller
	end, debug.traceback)
	if not ok then controller:Destroy() error("[OC] Initialization failed: " .. tostring(result), 0) end
	-- A repeated user-run loader cleans up only a previous OC instance from this registry.
	if type(shared) == "table" then
		local previous = shared.__OC_PHASE1_INSTANCE
		if previous and previous ~= controller and type(previous.Destroy) == "function" then previous:Destroy() end
		shared.__OC_PHASE1_INSTANCE = controller
	end
	return result
end

end
return entry()
